const PANE = 'deck'
const TITLE = 'Deck'
const PANE_COLUMNS = 66
const POLL_MS = 5000
// The two names the external verification is written under, in a run dir.
const VERIFY_NAMES = ['04-external-verify.json', 'external-verify.json']
// Finished shells shown under the running ones; the rest fold into « +N earlier ».
const DONE_SHELLS = 3

// ---------------------------------------------------------------- state

const main = atom({ plugin: 'deck', key: 'main' } as const, DEFAULT_MAIN)
const usage = atom({ plugin: 'deck', key: 'usage' } as const, DEFAULT_USAGE)
const architect = atom({ plugin: 'deck', key: 'architect' } as const, DEFAULT_ARCHITECT)
const agents = atom({ plugin: 'deck', key: 'agents' } as const, [])
const log = atom({ plugin: 'deck', key: 'log' } as const, [])
const turn = atom({ plugin: 'deck', key: 'turn' } as const, DEFAULT_TURN)
const receipt = atom({ plugin: 'deck', key: 'receipt' } as const, null)
const view = atom({ plugin: 'deck', key: 'view' } as const, DEFAULT_VIEW)
const roster = atom({ plugin: 'deck', key: 'roster' } as const, DEFAULT_ROSTER)
const run = atom({ plugin: 'deck', key: 'run' } as const, null)
const apexSteps = atom({ plugin: 'deck', key: 'apexSteps' } as const, NO_STEPS)
const verdict = atom({ plugin: 'deck', key: 'verdict' } as const, null)
const budget = atom({ plugin: 'deck', key: 'budget' } as const, null)
const shells = atom({ plugin: 'deck', key: 'shells' } as const, [])
const sessionRun = atom({ plugin: 'deck', key: 'sessionRun' } as const, null)
const openStep = atom({ plugin: 'deck', key: 'openStep' } as const, null)

// Module-level: a hot reload drops the environment and its timer with it.
let timer: Timer | undefined
// The pane is open: the 5 s timer runs only then.
let isPaneOpen = false
// Polls in a row that missed the run shown (settleRun).
let misses = 0
// The last run dir a poll found this session (kept through a miss or an ended run), or null:
// a different one is a new run, which clears the finished cards and shells.
let lastRunDir: string | null = null
// The poll under way (its number), or null: a second one waits, unless the first is stuck for
// STUCK_TICKS ticks, when it is given up and polling goes on.
let pollCount = 0
let pollUnderWay: number | null = null
let skippedTicks = 0
const STUCK_TICKS = 6

type ServerBlock = { type: string; id?: string; name?: string; tool_use_id?: string }

// Every read goes through these, so a value saved under an older shape still reads.
async function getMain($: EngineInterface): Promise<DeckMain> {
  return normalize(DEFAULT_MAIN, await read($, main))
}
async function getUsage($: EngineInterface): Promise<DeckUsage> {
  return normalize(DEFAULT_USAGE, await read($, usage))
}
async function getArchitect($: EngineInterface): Promise<DeckArchitect> {
  const a = normalize(DEFAULT_ARCHITECT, await read($, architect))
  return { ...a, consults: listOf(a.consults), ids: listOf(a.ids), seen: listOf(a.seen) }
}
async function getCards($: EngineInterface): Promise<DeckAgentCard[]> {
  return listOf<unknown>(await read($, agents)).map(normalizeCard)
}
async function getLog($: EngineInterface): Promise<DeckLogLine[]> {
  return normalizeLog(await read($, log))
}
async function getTurn($: EngineInterface): Promise<DeckTurn> {
  return normalize(DEFAULT_TURN, await read($, turn))
}
async function getView($: EngineInterface): Promise<DeckView> {
  return normalize(DEFAULT_VIEW, await read($, view))
}
async function getRoster($: EngineInterface): Promise<DeckRoster> {
  const r = normalize(DEFAULT_ROSTER, await read($, roster))
  return { architectTypes: listOf(r.architectTypes) }
}
async function getShells($: EngineInterface): Promise<DeckApexShell[]> {
  return listOf<DeckApexShell>(await read($, shells))
}

async function say($: EngineInterface, who: string, text: string, kind: DeckLogLine['kind'] = 'info', agentId: string | null = null) {
  const line: DeckLogLine = { at: await $.clock.now(), who, text, kind, agentId }
  await update($, log, list => [...normalizeLog(list), line].slice(-60))
}

async function whoIs($: EngineInterface, agentId: string | undefined) {
  if (!agentId) return 'main'
  const card = (await getCards($)).find(c => c.id === agentId)
  return card ? shorten(cardTitle(card), 14) : 'agent'
}

async function consultStarted($: EngineInterface, cfg: Config, id: string, via: string) {
  const t = await getTurn($)
  const moment = momentOf(t)
  const at = await $.clock.now()
  await update($, architect, a => startConsult(normalize(DEFAULT_ARCHITECT, a), { id, at, moment, via }))
  if (moment === 'before done') await update($, turn, x => ({ ...normalize(DEFAULT_TURN, x), isReviewing: true }))
  await say($, cfg.architectLabel.toLowerCase(), cfg.moments ? `${moment} · ${via}` : `consulted · ${via}`, 'consult')
}

async function consultEnded($: EngineInterface, cfg: Config, advice: string | null, id?: string) {
  const at = await $.clock.now()
  const first = advice?.split('\n').find(l => l.trim()) ?? null
  const text = first ? shorten(first.replace(/^[#>*\s-]+/, ''), 160) : null
  await update($, architect, a => endConsult(normalize(DEFAULT_ARCHITECT, a), at, text, id))
  await update($, turn, t => ({ ...normalize(DEFAULT_TURN, t), isReviewing: false }))
  await say($, cfg.architectLabel.toLowerCase(), text ? `advice: ${shorten(text, 60)}` : 'advice returned', 'consult')
}

async function noteAdvice($: EngineInterface, cfg: Config, advice: string) {
  await update($, architect, x => ({ ...normalize(DEFAULT_ARCHITECT, x), lastAdvice: advice }))
  await say($, cfg.architectLabel.toLowerCase(), `advice: ${shorten(advice, 60)}`, 'consult')
}

async function isArchitectType($: EngineInterface, cfg: Config, type: string) {
  return cfg.architect.test(type) || (await getRoster($)).architectTypes.includes(type)
}

async function openPane($: EngineInterface) {
  // columns apply when docked beside the transcript, rows when seated inline above the prompt.
  const opened = await $.ui.open({ id: PANE, title: TITLE, columns: PANE_COLUMNS, rows: 8 })
  // Open, even when not placed yet (seated once a surface places it): polled from now on.
  isPaneOpen = true
  startPolling($)
  return opened
}

async function resetAll($: EngineInterface) {
  await update($, main, m => ({ ...DEFAULT_MAIN, model: normalize(DEFAULT_MAIN, m).model, mode: normalize(DEFAULT_MAIN, m).mode }))
  await update($, architect, () => DEFAULT_ARCHITECT)
  await update($, agents, () => [])
  await update($, log, () => [])
  await update($, turn, () => DEFAULT_TURN)
  await update($, receipt, () => null)
  await update($, view, () => DEFAULT_VIEW)
  // The context gauge waits for the next measurement rather than showing the pre-clear fill.
  await update($, usage, x => ({ ...normalize(DEFAULT_USAGE, x), pct: null, tokens: null }))
  // The run comes back on the next poll; its live steps start over.
  await update($, run, () => null)
  await update($, apexSteps, () => NO_STEPS)
  await update($, verdict, () => null)
  await update($, budget, () => null)
  await update($, shells, () => [])
  await update($, sessionRun, () => null)
  await update($, openStep, () => null)
}

/** The session's cost read fresh, not from the last measurement: the receipt subtracts two of these. */
async function costNow($: EngineInterface): Promise<number | null> {
  const u = await $.session.usage().catch(() => null)
  return u?.cost?.usd ?? null
}

async function noteMode($: EngineInterface, mode: string | undefined) {
  if (mode) await update($, main, m => (normalize(DEFAULT_MAIN, m).mode === mode ? normalize(DEFAULT_MAIN, m) : { ...normalize(DEFAULT_MAIN, m), mode }))
}

// ---------------------------------------------------------------- APEX run (polled)

// Reads a field of an engine record whose shape varies per tool; a value that is not a
// non-empty string reads as undefined.
function stringField(record: unknown, key: string): string | undefined {
  if (typeof record !== 'object' || record === null) return undefined
  const value: unknown = Reflect.get(record, key)
  return typeof value === 'string' && value !== '' ? value : undefined
}

function numberField(record: unknown, key: string): number | undefined {
  if (typeof record !== 'object' || record === null) return undefined
  const value: unknown = Reflect.get(record, key)
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined
}

// A row's text: a string as is, else its text blocks joined; another shape reads as empty.
function rowText(content: unknown): string {
  if (typeof content === 'string') return content
  if (!Array.isArray(content)) return ''
  const parts: string[] = []
  for (const block of content) {
    const text = stringField(block, 'type') === 'text' ? stringField(block, 'text') : undefined
    if (text !== undefined) parts.push(text)
  }
  return parts.join('\n')
}

// A run folder: its name, its newest time (with a context file: that file's or its newest .md
// file's; without: its newest step file's), its context file's mtime when it has one, its .md files.
type RunDir = { dir: string; mtimeMs: number; context?: number; files: { name: string; mtimeMs: number }[] }

// Folders listed per poll: the LISTED_DIRS ranked newest that are runs, plus the newest with a
// context file wherever it ranks. Cost before that: 1 stat per folder with a context file, 2 per
// folder without (the failed context stat, then the folder's own).
const LISTED_DIRS = 3

// The newest run folder, or undefined. Ranked by its context file's mtime, else by the folder's
// own (adding a file moves it; editing one does not), then listed in rank order and the newest
// time of each decides. A folder without a context file and without a step file is no run: it
// takes no slot and is never chosen.
async function newestRun($: EngineInterface, root: string): Promise<RunDir | undefined> {
  let entries
  try {
    entries = await $.fs.list(root)
  } catch {
    // No .claude/output/apex here (or unreadable): no run to show.
    return undefined
  }
  const ranked: { dir: string; key: number; context?: number }[] = []
  for (const entry of entries) {
    if (entry.kind !== 'dir') continue
    try {
      const stat = await $.fs.stat(`${root}/${entry.name}/00-context.md`)
      ranked.push({ dir: entry.name, key: stat.mtimeMs, context: stat.mtimeMs })
      continue
    } catch {
      // No context file: the folder ranks by its own mtime, read below.
    }
    try {
      ranked.push({ dir: entry.name, key: (await $.fs.stat(`${root}/${entry.name}`)).mtimeMs })
    } catch {
      // Vanished between list and stat: skipped.
    }
  }
  ranked.sort((a, b) => b.key - a.key)
  const newestContext = ranked.find(r => r.context !== undefined)
  let best: RunDir | undefined
  let slots = 0
  for (const candidate of ranked) {
    if (slots >= LISTED_DIRS && candidate !== newestContext) continue
    let files: { name: string; mtimeMs: number }[]
    try {
      files = (await $.fs.list(`${root}/${candidate.dir}`))
        .filter(e => e.kind === 'file' && e.name.endsWith('.md'))
        .map(e => ({ name: e.name, mtimeMs: e.mtimeMs }))
    } catch {
      // Unreadable folder: its context file's time alone, if any.
      files = []
    }
    const mtimeMs =
      candidate.context === undefined ? newestStep(files) : Math.max(candidate.context, ...files.map(f => f.mtimeMs))
    // Without a context file, a folder with no step file is not a run: no slot, never chosen.
    if (mtimeMs === -Infinity) continue
    slots += 1
    if (best !== undefined && mtimeMs <= best.mtimeMs) continue
    best = { dir: candidate.dir, mtimeMs, files, ...(candidate.context === undefined ? {} : { context: candidate.context }) }
  }
  return best
}

// HEAD's branch, or undefined: no repo here, or a worktree whose .git is a file.
async function readHead($: EngineInterface, cwd: string): Promise<string | undefined> {
  try {
    return headBranch(await $.fs.read(`${cwd}/.git/HEAD`))
  } catch {
    // Unreadable HEAD: branch unknown, shown.
    return undefined
  }
}

// The session's last main-loop Skill(apex) call, or null (an older shape reads as none).
async function getSessionRun($: EngineInterface): Promise<DeckApexSessionRun | null> {
  const value: unknown = await read($, sessionRun)
  const startedAt = numberField(value, 'startedAt')
  const lastAt = numberField(value, 'lastAt')
  if (startedAt === undefined || lastAt === undefined) return null
  const turnEndAt = numberField(value, 'turnEndAt')
  const merged = Reflect.get(Object(value), 'merged') === true
  return { startedAt, lastAt, args: stringField(value, 'args') ?? '', turnEndAt: turnEndAt ?? null, merged }
}

// One change to the session run, written only when there is one and the change moved something.
async function changeSessionRun($: EngineInterface, fn: (value: DeckApexSessionRun) => DeckApexSessionRun): Promise<void> {
  await record(async () => {
    const current = await getSessionRun($)
    if (current === null) return
    const next = fn(current)
    if (JSON.stringify(next) !== JSON.stringify(current)) await update($, sessionRun, () => next)
  })
}

// New activity (a main turn start, a tool call, an agent spawn): the run clock runs again.
const wakeRun = ($: EngineInterface): Promise<void> =>
  changeSessionRun($, x => (x.turnEndAt === null || x.turnEndAt === undefined ? x : { ...x, turnEndAt: null }))

// The open step, or none (an unknown name reads as none).
async function getOpenStep($: EngineInterface): Promise<DeckApexStepName | null> {
  const value: unknown = await read($, openStep)
  return STEP_NAMES.find(n => n === value) ?? null
}

// The live run folder, else the session's Skill(apex) call (HEAD read only when there is one).
async function scan($: EngineInterface): Promise<DeckApexRun | null> {
  const cwd = await $.session.cwd()
  const folder = await scanFolder($, cwd)
  if (folder !== null) return folder
  const at = await getSessionRun($)
  if (at === null) return null
  return sessionRunOf(at, await readHead($, cwd), await $.clock.now())
}

async function scanFolder($: EngineInterface, cwd: string): Promise<DeckApexRun | null> {
  const root = `${cwd}/.claude/output/apex`
  const newest = await newestRun($, root)
  if (newest === undefined) return null
  let parsed: DeckApexRun
  let liveMs: number
  if (newest.context !== undefined) {
    let text: string
    try {
      text = await $.fs.read(`${root}/${newest.dir}/00-context.md`)
    } catch {
      // Vanished between stat and read, or over 4 MiB: nothing shown this round.
      return null
    }
    parsed = parseContext(text, newest.dir)
    liveMs = newest.context
  } else {
    parsed = runFromFiles(newest.dir, newest.files)
    // Only a finish step file: the run ended.
    if (parsed.currentStep === undefined) return null
    liveMs = newest.mtimeMs
  }
  const now = await $.clock.now()
  if (!isLive(parsed, liveMs, now)) return null
  const head = await readHead($, cwd)
  // Without a context file the header names the folder (no branch); hidden on the trunk, live 1 h.
  if (newest.context === undefined && !bareShown(parsed, liveMs, head, now)) return null
  return onBranch(parsed, head) ? { ...parsed, dir: newest.dir } : null
}

// The state library reads and writes named atoms only: one writer per atom, each writing
// only when the value changed.
async function putVerdict($: EngineInterface, value: DeckApexVerdict | null): Promise<void> {
  if (JSON.stringify(await read($, verdict)) === JSON.stringify(value)) return
  await update($, verdict, () => value)
}

async function putBudget($: EngineInterface, value: DeckApexBudget | null): Promise<void> {
  if (JSON.stringify(await read($, budget)) === JSON.stringify(value)) return
  await update($, budget, () => value)
}

// The live steps, or none (an older shape reads as none).
async function getSteps($: EngineInterface): Promise<DeckApexSteps> {
  const s = normalize(NO_STEPS, await read($, apexSteps))
  return { runKey: typeof s.runKey === 'string' ? s.runKey : null, steps: listOf(s.steps), current: s.current ?? null }
}

// One change to the live steps, written only when it changed something. Steps count only while
// a run is live: a Skill(apex) call set the key, else the shown run folder gives it.
async function changeSteps($: EngineInterface, fn: (value: DeckApexSteps, runKey: string) => DeckApexSteps): Promise<void> {
  await record(async () => {
    const current = await getSteps($)
    const runKey = current.runKey ?? (await read($, run))?.dir ?? null
    if (runKey === null) return
    const next = fn(current, runKey)
    if (next !== current) await update($, apexSteps, () => next)
  })
}

async function changeShells($: EngineInterface, fn: (value: DeckApexShell[]) => DeckApexShell[]): Promise<void> {
  const current = await getShells($)
  if (fn(current) === current) return
  await update($, shells, list => fn(listOf<DeckApexShell>(list)))
}

// The run's external verification, from whichever of its two names was written last;
// re-read only when that file's mtime moved.
async function refreshVerdict($: EngineInterface, found: DeckApexRun | null): Promise<void> {
  const dir = found?.dir
  // A session run has no folder: nothing to list.
  if (dir === undefined || isSessionDir(dir)) return putVerdict($, null)
  const runDir = `${await $.session.cwd()}/.claude/output/apex/${dir}`
  let newest: { name: string; mtimeMs: number } | null = null
  try {
    for (const entry of await $.fs.list(runDir)) {
      if (entry.kind !== 'file' || !VERIFY_NAMES.includes(entry.name)) continue
      newest = pickVerdict(newest, { name: entry.name, mtimeMs: entry.mtimeMs })
    }
  } catch {
    // The run directory vanished: no verification to show.
    newest = null
  }
  if (newest === null) return putVerdict($, null)
  const current = await read($, verdict)
  if (current !== null && current.dir === dir && current.mtimeMs === newest.mtimeMs) return
  let next: DeckApexVerdict | null = null
  try {
    const parsed = parseVerdict(await $.fs.read(`${runDir}/${newest.name}`))
    if (parsed !== null) next = { dir, mtimeMs: newest.mtimeMs, ...parsed }
  } catch {
    // Vanished between list and read, or over 4 MiB: shown as pending.
    next = null
  }
  await putVerdict($, next)
}

// The run's correction budget, from the names in ~/.claude/apex-correction-budget (one file
// per round used or granted).
async function refreshBudget($: EngineInterface, found: DeckApexRun | null): Promise<void> {
  const dir = found?.dir
  const home = await $.env.get('HOME')
  if (dir === undefined || isSessionDir(dir) || home === undefined || home === '') return putBudget($, null)
  let names: string[]
  try {
    names = (await $.fs.list(`${home}/.claude/apex-correction-budget`)).map(entry => entry.name)
  } catch {
    // No round was ever claimed on this machine: no budget to show.
    names = []
  }
  await putBudget($, budgetOf(names, dir))
}

// A subagent's still running shells close once it is killed, fails or leaves the agent list:
// their notification would only ever reach that loop. Read only while such a shell runs.
async function snapshotShells($: EngineInterface): Promise<void> {
  const list = await getShells($)
  if (!list.some(s => s.status === 'running' && s.ownerAgentId !== undefined)) return
  const listed = await $.agent.list()
  const owners = listed.map(a => ({ id: a.id, type: a.type, status: a.status }))
  const [cards, a] = await Promise.all([getCards($), getArchitect($)])
  const known = [...cards.map(c => c.id), ...a.ids]
  const at = await $.clock.now()
  await changeShells($, current => closeBySnapshot(current, owners, known, at))
}

// A new run: the finished cards and shells go, the running ones stay; receipt, log, main untouched.
async function clearForNewRun($: EngineInterface): Promise<void> {
  const cards = await getCards($)
  if (clearFinished(cards, []).cards !== cards) {
    await update($, agents, list => clearFinished(listOf<unknown>(list).map(normalizeCard), []).cards)
  }
  await changeShells($, current => clearFinished([], current).shells)
  await update($, openStep, () => null)
}

// One poll: run (its phase moves to the log), phases, verdict, budget, owned shells.
async function refresh($: EngineInterface): Promise<void> {
  const scanned = await scan($)
  const prev = await read($, run)
  const settled = settleRun(prev, scanned, misses)
  misses = settled.misses
  const found = settled.run
  if (JSON.stringify(prev) !== JSON.stringify(found)) await update($, run, () => found)
  const note = phaseNote(prev, found)
  if (note !== null) await say($, 'apex', note)
  const sw = runSwitch(lastRunDir, found?.dir ?? null)
  lastRunDir = sw.last
  if (sw.isNew) await clearForNewRun($)
  await refreshVerdict($, found)
  await refreshBudget($, found)
  await snapshotShells($)
}

function onTick($: EngineInterface): void {
  if (pollUnderWay !== null && skippedTicks < STUCK_TICKS) {
    skippedTicks += 1
    return
  }
  pollCount += 1
  const mine = pollCount
  pollUnderWay = mine
  skippedTicks = 0
  refresh($)
    .catch(() => {
      // A failed scan or a refused write leaves the figures as they were; the next tick tries again.
    })
    .finally(() => {
      // A poll given up as stuck no longer owns the slot when it settles at last.
      if (pollUnderWay === mine) pollUnderWay = null
    })
}

// One poll now, and the 5 s timer while the pane is open.
function startPolling($: EngineInterface): void {
  if (timer === undefined) timer = $.clock.every(POLL_MS, () => onTick($))
  pollOnce($)
}

function stopPolling(): void {
  timer?.cancel()
  timer = undefined
}

// A single poll (a prompt, a finished main turn): the log's apex lines fill with the pane closed.
function pollOnce($: EngineInterface): void {
  $.clock.after(0, () => onTick($))
}

// Runs `write`; a refused state write leaves the figures as they were (an observer never fails
// the event it watches).
async function record(write: () => Promise<void>): Promise<void> {
  try {
    await write()
  } catch {
    // Figures only: the next step, call or poll writes again.
  }
}

/**
 * The run's live step a tool call stands for: edits from every loop, gate / Codex / ship from the
 * main loop's Bash only. A refused call, or a failed edit, is no step. Called from the one
 * unmatched tool.call observer (the engine allows one per event).
 */
async function noteCallStep($: EngineInterface, e: unknown, ran: { result?: unknown; isError?: boolean }): Promise<void> {
  const isRefused = ran.result === undefined && ran.isError !== true
  const tool = stringField(e, 'tool') ?? ''
  const input = { file_path: stringField(e, 'file_path'), notebook_path: stringField(e, 'notebook_path'), command: stringField(e, 'command') }
  const name = isRefused ? null : classifyCall(tool, input, stringField(e, 'agentId') !== undefined)
  const isFailedEdit = (name === 'edit' || name === 'plan') && ran.isError === true
  if (name === null || isFailedEdit) return
  const stdout = stringField(ran.result, 'stdout') ?? ''
  const command = input.command ?? ''
  const path = input.file_path ?? input.notebook_path
  const codex = name === 'Codex' ? parseCodex(stdout) : null
  const out = { stdout, stderr: stringField(ran.result, 'stderr') ?? '', returnCodeInterpretation: stringField(ran.result, 'returnCodeInterpretation') ?? '' }
  const evidence =
    name === 'Codex'
      ? (codex ?? {})
      : name === 'gate'
        ? gateEvidence(command, out, ran.isError === true)
        : name === 'ship'
          ? shipEvidence(command, stdout)
          : path === undefined
            ? {}
            : { files: [pathTail(path)] }
  const at = await $.clock.now()
  await changeSteps($, (s, key) => seeStep(s, key, name, at, evidence))
  if (name === 'ship' && ran.isError !== true && isMergeCall(command)) await changeSessionRun($, x => (x.merged === true ? x : { ...x, merged: true }))
}

/** An implementer, test-runner or reviewer started: its step, with what it does and on which model. */
async function noteAgentStep($: EngineInterface, subagentType: string, description: string, agentId: string, model: string): Promise<void> {
  const name = classifyAgent(subagentType)
  if (name === null) return
  const at = await $.clock.now()
  const detail = `${description} (${modelFamily(model)})`
  await changeSteps($, (s, key) => seeStep(s, key, name, at, { agentId, detail }))
}

/** A step's agent ended: a reviewer's verdict (anchored) and the lines after it, else its answer's first lines. */
async function endAgentStep($: EngineInterface, agentId: string, answer: string, reason: string): Promise<void> {
  const at = await $.clock.now()
  const isReview = (await getSteps($)).steps.some(x => x.agentId === agentId && x.name === 'review')
  const verdict = isReview ? parseReview(answer) : null
  const lines = isReview ? reviewLines(answer) : answerLines(answer)
  await changeSteps($, s => endAgent(s, agentId, at, verdict, { lines, isFailed: reason !== 'answer' }))
}

const alertText = (a: DeckApexAlert) =>
  a.kind === 'step'
    ? `✗ step ${a.step} failed`
    : a.kind === 'verify'
      ? `✗ external verify ${a.verdict} · ${plural(a.findings, 'finding')}`
      : `■ correction budget spent · ${a.rounds}/${a.cap} rounds`

/** /deck and its aliases: open (the default), close, reset, layout <auto|compact|wide|mini>. */
async function runCommand($: EngineInterface, args: string) {
  const [verb = 'open', arg = ''] = args.trim().split(/\s+/)
  if (verb === 'close') {
    await $.ui.close({ id: PANE })
    isPaneOpen = false
    stopPolling()
    return { text: 'Deck closed.' }
  }
  if (verb === 'reset') {
    await resetAll($)
    return { text: 'Deck reset.' }
  }
  if (verb === 'layout') {
    const layout: DeckLayout | null = arg === 'compact' || arg === 'wide' || arg === 'auto' || arg === 'mini' ? arg : null
    if (!layout) return { text: 'Usage: /deck layout auto|compact|wide|mini' }
    await update($, view, v => ({ ...normalize(DEFAULT_VIEW, v), layout }))
    const opened = await openPane($)
    return { text: opened.isPlaced ? `Deck layout: ${layout}.` : `Layout set to ${layout}; the pane is not shown yet: ${opened.reason}` }
  }
  const opened = await openPane($)
  if (!opened.isPlaced) return { text: `Deck is not shown yet: ${opened.reason}` }
  return { text: 'Deck opened. Focus it with ctrl+x tab; 1-6 expand cards.' }
}

// ---------------------------------------------------------------- hooks

export const register: Register = (on, options) => {
  const cfg = parseConfig(options)
  const C = PALETTES[cfg.palette]

  on('session.start', async ($, e, next) => {
    // Each command on its own: one refused leaves the others registered.
    try {
      await $.command.register({
        name: 'deck',
        description: 'Deck, the live agent and APEX dashboard: open, close, reset, or set the layout',
        argumentHint: '[open|close|reset|layout auto|compact|wide|mini]',
      })
    } catch {
      // Refused: no /deck this session; the aliases and the observers still run.
    }
    try {
      await $.command.register({ name: 'apex-pane', description: 'Opens the deck pane (alias of /deck)' })
    } catch {
      // Refused: no /apex-pane this session; /deck still opens the pane.
    }
    try {
      await $.command.register({ name: 'task-board', description: 'Opens the deck pane (alias of /deck)' })
    } catch {
      // Refused: no /task-board this session; /deck still opens the pane.
    }
    // A host without usage (headless, an SDK host, a session not yet bound) just starts without it.
    const u = await $.session.usage().catch(() => null)
    if (u) {
      await update($, usage, x => ({
        ...normalize(DEFAULT_USAGE, x),
        pct: u.context.percent ?? null,
        tokens: u.context.tokens ?? null,
        window: u.context.window,
        costUsd: u.cost?.usd ?? null,
        limits: u.rateLimits.map(r => ({ kind: r.kind, pct: r.percentUsed })),
      }))
    }
    return next(e)
  })

  on('session.end', async ($, e, next) => {
    // The next session's first run is no new run.
    lastRunDir = null
    if (e.reason === 'clear') {
      // A /clear starts every figure over; the poll is kept for it.
      misses = 0
      await resetAll($)
    } else {
      isPaneOpen = false
      stopPolling()
    }
    return next(e)
  })

  // The pane closed (its close button, /deck close, another plugin): the 5 s poll stops.
  on('ui.close', async ($, e, next) => {
    const closed = await next(e)
    if (e.id === PANE) {
      isPaneOpen = false
      stopPolling()
    }
    return closed
  })

  on('command.run', { command: 'deck' }, async ($, e) => runCommand($, e.args))
  on('command.run', { command: 'apex-pane' }, async ($, e) => runCommand($, e.args))
  on('command.run', { command: 'task-board' }, async ($, e) => runCommand($, e.args))

  on('prompt.submit', ($, e, next) => {
    pollOnce($)
    return next(e)
  })

  on('classic.UserPromptSubmit', async ($, e, next) => {
    await noteMode($, e.permission_mode)
    return next(e)
  })

  on('agent.offer', async ($, e, next) => {
    const offered = await next(e)
    if (cfg.architect.test(e.agent) || (cfg.matchDescriptions && cfg.architect.test(e.description))) {
      await update($, roster, r => {
        const x = normalize(DEFAULT_ROSTER, r)
        return x.architectTypes.includes(e.agent) ? x : { architectTypes: [...listOf<string>(x.architectTypes), e.agent].slice(-20) }
      })
    }
    return offered
  })

  on('turn.start', async ($, e, next) => {
    const [now, cost] = await Promise.all([$.clock.now(), costNow($)])
    await update($, turn, () => ({ ...DEFAULT_TURN, startedAt: now, costAtStart: cost }))
    await update($, main, m => ({ ...normalize(DEFAULT_MAIN, m), isRunning: true }))
    if (stringField(e, 'agentId') === undefined) await wakeRun($)
    // A background architect's report reaches the main loop as the text opening this turn. The
    // SubagentHandback tool call (in tool.call) normally carries it first; this is the fallback.
    const back = e.text ? handbackOf(e.text) : null
    const a = back ? await getArchitect($) : null
    if (back && a && a.ids.includes(back.from)) {
      const advice = adviceLine(back.body)
      if (advice && advice !== a.lastAdvice) await noteAdvice($, cfg, advice)
    } else if (e.text) {
      const p = promptLine(e.text)
      await say($, p.who, p.text)
    }
    return next(e)
  })

  on('turn.step', async function* ($, e, next) {
    // The main loop's model is known when its request starts; a long first request shouldn't read "—".
    if (!e.agentId) {
      await update($, main, m => {
        const x = normalize(DEFAULT_MAIN, m)
        return { ...x, model: e.model, effort: String(e.effort ?? x.effort), steps: x.steps + 1 }
      })
    }
    const result = yield* next(e)
    const id = e.agentId
    if (!id) return result
    const cards = await getCards($)
    if (cards.some(c => c.id === id)) {
      const step = { model: e.model, usage: result.usage, stopReason: result.stopReason }
      await update($, agents, list => listOf<unknown>(list).map(normalizeCard).map(c => (c.id === id ? applyStep(c, step) : c)))
      if (result.stopReason === 'max_tokens') await say($, await whoIs($, id), 'hit max_tokens', 'error', id)
    }
    return result
  })

  on('session.measure', async ($, e, next) => {
    await update($, usage, x => ({
      ...normalize(DEFAULT_USAGE, x),
      pct: e.context.percent ?? null,
      tokens: e.context.tokens ?? null,
      window: e.context.window,
      costUsd: e.cost?.usd ?? null,
      limits: e.rateLimits.map(r => ({ kind: r.kind, pct: r.percentUsed })),
    }))
    return next(e)
  })

  on('session.compact', async ($, e, next) => {
    const done = await next(e)
    if (!e.agentId && e.trigger !== 'precompute') {
      const now = await $.clock.now()
      await update($, usage, x => {
        const u = normalize(DEFAULT_USAGE, x)
        return { ...u, compactions: u.compactions + 1, lastCompactAt: now }
      })
      await say($, 'main', `context compacted (${e.trigger})`)
    }
    return done
  })

  on('tool.call', async ($, e, next) => {
    const ran = await next(e)
    await wakeRun($)
    await noteCallStep($, e, ran)
    // A refused call carries neither a result nor an error. An inference, not the refusal's own
    // field: a tool that answers with an undefined result would read as refused too (log text only).
    const isRefused = ran.result === undefined && ran.isError !== true
    // A background agent hands its report back through this tool; an architect's report is its advice.
    if (String(e.tool) === 'SubagentHandback') {
      const message = (e as unknown as { message?: unknown }).message
      const a = e.agentId ? await getArchitect($) : null
      if (a && e.agentId && a.ids.includes(e.agentId) && typeof message === 'string') {
        const advice = adviceLine(message)
        if (advice && advice !== a.lastAdvice) await noteAdvice($, cfg, advice)
      }
      return ran
    }
    if (e.tool === 'Agent') return ran
    const hasFailed = !isRefused && ran.isError === true
    const isEdit = !hasFailed && !isRefused && EDIT_TOOLS.has(e.tool)
    const t0 = await getTurn($)
    if (isEdit || hasFailed || (!e.agentId && t0.errorStreak > 0)) {
      await update($, turn, t => afterCall(normalize(DEFAULT_TURN, t), { inSubagent: Boolean(e.agentId), hasFailed, isEdit }))
    }
    const text = shorten(describeInput(e.tool, e), 64)
    if (e.agentId) {
      const id = e.agentId
      await update($, agents, list =>
        listOf<unknown>(list)
          .map(normalizeCard)
          .map(c => (c.id === id ? noteTool(c, { tool: e.tool, text, isError: hasFailed || isRefused }) : c)),
      )
    }
    // The log keeps what is worth a glance: refusals, errors and edits; the rest is on the cards.
    if (isRefused) await say($, await whoIs($, e.agentId), `${text}  refused`, 'error', e.agentId ?? null)
    else if (hasFailed) await say($, await whoIs($, e.agentId), `${text}  ✗`, 'error', e.agentId ?? null)
    else if (isEdit) await say($, await whoIs($, e.agentId), text, 'info', e.agentId ?? null)
    return ran
  })

  // Background shell: run_in_background, or ctrl+B / auto-background, all answer a backgroundTaskId.
  on('tool.call', { tool: 'Bash' }, async ($, e, next) => {
    const ran = await next(e)
    const id = stringField(ran.result, 'backgroundTaskId')
    if (id !== undefined) {
      await record(async () => {
        const startedAt = await $.clock.now()
        const label = stringField(e, 'description') ?? stringField(e, 'command') ?? 'shell'
        const toolUseId = stringField(e, 'tool_use_id')
        // Set only inside a subagent loop: its shells close with it.
        const ownerAgentId = stringField(e, 'agentId')
        await changeShells($, current =>
          addShell(current, {
            id,
            label,
            startedAt,
            ...(toolUseId === undefined ? {} : { toolUseId }),
            ...(ownerAgentId === undefined ? {} : { ownerAgentId }),
          }),
        )
      })
    }
    return ran
  }).catch(($, e, next) => next(e))

  // A main-loop Skill(apex) call that ran: a run without a folder (yet), a new run once any run
  // was seen. A subagent's call, another skill, a failed or refused call: nothing.
  on('tool.call', { tool: 'Skill' }, async ($, e, next) => {
    const ran = await next(e)
    if (stringField(e, 'skill') === 'apex' && !e.agentId && ran.isError !== true && ran.result !== undefined) {
      await record(async () => {
        const now = await $.clock.now()
        const sw = callSwitch(lastRunDir, sessionKey(now))
        lastRunDir = sw.last
        if (sw.isNew) await clearForNewRun($)
        await update($, sessionRun, () => ({ startedAt: now, lastAt: now, args: shorten(stringField(e, 'args') ?? '', 40) }))
        // Each call starts the run's live steps over, keyed as the session run.
        await update($, apexSteps, () => startSteps(sessionKey(now)))
        await update($, openStep, () => null)
      })
      pollOnce($)
    }
    return ran
  }).catch(($, e, next) => next(e))

  // A shell stopped by TaskStop gets no notification row: closed as killed. TaskStop also stops
  // agents; stopShell leaves those alone.
  on('tool.call', { tool: 'TaskStop' }, async ($, e, next) => {
    const ran = await next(e)
    if (ran.isError !== true && ran.result !== undefined) {
      const id = stringField(ran.result, 'task_id') ?? stringField(e, 'task_id') ?? stringField(e, 'shell_id')
      if (id !== undefined) {
        await record(async () => {
          const at = await $.clock.now()
          await changeShells($, current => stopShell(current, id, at))
        })
      }
    }
    return ran
  }).catch(($, e, next) => next(e))

  // A background shell's notification row: the one completion signal a shell has. A render hook
  // never writes state, so the write is deferred to a timer; the row itself is drawn unchanged.
  on('ui.render', { component: 'UserMessage', props: { origin: { kind: 'task-notification' } } }, ($, e, next) => {
    const task: unknown = e.props.task
    const note: Notification = {}
    const id = stringField(task, 'id')
    const toolUseId = stringField(task, 'toolUseId')
    const status = stringField(task, 'status')
    const durationMs = numberField(task, 'durationMs')
    if (id !== undefined) note.id = id
    if (toolUseId !== undefined) note.toolUseId = toolUseId
    if (status !== undefined) note.status = status
    if (durationMs !== undefined) note.durationMs = durationMs
    if (note.status !== undefined) {
      $.clock.after(0, () => {
        $.clock
          .now()
          .then(at => changeShells($, current => finishByNotification(current, note, at)))
          .catch(() => {
            // State refused: the shell stays running until its owner's end or a later redraw.
          })
      })
    }
    return next(e)
  })

  // A server-side review tool never reaches tool.call: it shows only in the assistant's rows.
  // A subagent's shell notifies that subagent's loop only: its row never reaches the main
  // transcript, so it is read here. Read before next: the row is relayed unchanged.
  on('session.append', async ($, e, next) => {
    const agentId = e.agentId
    if (agentId !== undefined && agentId !== '' && e.origin.kind === 'task-notification') {
      const notes = parseTaskNotifications(rowText(e.message.content))
      if (notes.length > 0) {
        await record(async () => {
          const at = await $.clock.now()
          await changeShells($, current => notes.reduce((list, note) => finishByNotification(list, note, at), current))
        })
      }
    }
    if (!e.agentId && e.message.type === 'assistant') {
      const a = await getArchitect($)
      // Consults this row opened: their result may be in the same row, after the stale read above.
      const opened = new Set<string>()
      for (const block of e.message.content as unknown as readonly ServerBlock[]) {
        if (block.type === 'server_tool_use' && block.name && block.id && cfg.architect.test(block.name)) {
          if (a.seen.includes(block.id)) continue
          const id = block.id
          await update($, architect, x => {
            const y = normalize(DEFAULT_ARCHITECT, x)
            return { ...y, seen: [...listOf<string>(y.seen), id].slice(-60) }
          })
          opened.add(id)
          await consultStarted($, cfg, id, `${block.name} tool`)
        } else if (block.type.endsWith('_tool_result') && block.tool_use_id) {
          const id = block.tool_use_id
          const isOpen = opened.has(id) || (await getArchitect($)).consults.some(c => c.id === id && c.endAt === null)
          if (isOpen) await consultEnded($, cfg, null, id)
        }
      }
    }
    return next(e)
  })

  on('agent.spawn', async ($, e, next) => {
    const started = await next(e)
    if (!e.parentAgentId) await noteMode($, e.permissionMode)
    if (!started.agentId) return started
    const id = started.agentId
    await wakeRun($)
    await noteAgentStep($, e.subagentType, e.description, id, started.model)
    if (await isArchitectType($, cfg, e.subagentType)) {
      await update($, architect, a => {
        const x = normalize(DEFAULT_ARCHITECT, a)
        return { ...x, ids: [...listOf<string>(x.ids), id].slice(-40) }
      })
      await consultStarted($, cfg, id, e.subagentType.split(':').pop() ?? 'agent')
      return started
    }
    const card: DeckAgentCard = {
      ...normalizeCard({}),
      id,
      type: e.name ?? e.subagentType,
      model: started.model,
      description: e.description,
      spawnedAt: await $.clock.now(),
    }
    await update($, agents, list => [...listOf<unknown>(list).map(normalizeCard), card].slice(-24))
    await say($, shorten(cardTitle(card), 12), `spawned · ${card.type}`, 'info', id)
    return started
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    const id = e.agentId
    const now = await $.clock.now()
    if (!id) {
      const [t, cards, cost] = await Promise.all([getTurn($), getCards($), costNow($)])
      const r = receiptOf(t, {
        durationMs: e.durationMs,
        agentsSince: cards.filter(c => c.spawnedAt >= t.startedAt).length,
        costNow: cost,
        reason: e.reason,
      })
      await update($, receipt, () => r)
      await update($, main, m => ({ ...normalize(DEFAULT_MAIN, m), isRunning: false }))
      // The main turn's end: the run clock stops here once no agent or shell of the run runs.
      await changeSessionRun($, x => ({ ...x, turnEndAt: now }))
      pollOnce($)
      return done
    }
    // Any subagent, the architect too: its still running shells could only ever notify it.
    await record(() => changeShells($, current => shellsAfterTurn(current, id, e.reason, now)))
    await endAgentStep($, id, e.answer, e.reason)
    if ((await getArchitect($)).ids.includes(id)) {
      await consultEnded($, cfg, e.answer, id)
      return done
    }
    const cards = await getCards($)
    if (cards.some(c => c.id === id)) {
      const status = e.reason === 'answer' ? 'done' : e.reason === 'aborted' ? 'stopped' : 'failed'
      await update($, agents, list =>
        listOf<unknown>(list)
          .map(normalizeCard)
          .map(c => (c.id === id ? { ...c, status, endedAt: now, answer: shorten(e.answer, 400) } : c)),
      )
      const card = cards.find(c => c.id === id)
      const took = card ? fmtDuration(now - card.spawnedAt) : ''
      await say($, await whoIs($, id), status === 'done' ? `done · ${took}` : status, status === 'done' ? 'done' : 'error', id)
    }
    return done
  })

  // ---------------------------------------------------------------- drawing

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    // Drawn means open (a hot reload forgets the flag; the surface does not): polled while it is.
    if (!isPaneOpen) {
      isPaneOpen = true
      startPolling($)
    }
    const els = $.ui.resolve(e)
    const { Box, Text, Button } = els
    // Clients draw on terminal and desktop only; elsewhere the same frame as static text.
    const hasClient = 'Client' in els && (e.surface === 'terminal' || e.surface === 'desktop')
    const [m, u, a, cards, lines, t, r, v, apexRun, st, sr, vd, bg, sh, now, open] = await Promise.all([
      getMain($),
      getUsage($),
      getArchitect($),
      getCards($),
      getLog($),
      getTurn($),
      read($, receipt),
      getView($),
      read($, run),
      getSteps($),
      getSessionRun($),
      read($, verdict),
      read($, budget),
      getShells($),
      $.clock.now(),
      getOpenStep($),
    ])
    const W = Math.max(40, e.props.bodyColumns)
    const layout = v.layout ?? cfg.layout
    const isWide = layout === 'wide' || (layout === 'auto' && W >= 110)
    const colW = isWide ? Math.floor((W - 2) / 2) : W
    const modelName = prettyModel(m.model)
    const viewed = e.props.view?.agentId ?? null
    const advising = isAdvising(a)
    const running = cards.filter(c => c.status === 'running')
    const showArchitect = a.consults.length > 0 || a.ids.length > 0
    const motion = cfg.motion && hasClient
    // A panel with nothing to show yet takes no room: most sessions never spawn an agent.
    const isEmpty: Record<Panel, boolean> = {
      main: false,
      architect: !showArchitect,
      agents: cards.length === 0,
      receipt: !m.isRunning && !r,
      log: false,
    }
    const panels = cfg.panels.filter(p => !isEmpty[p])

    // A connector between panels: animated while its flow is live, a dim line otherwise.
    const rail = (key: string, active: boolean, color: string, width: number, marks: number[] = [], isMerge = false) =>
      motion ? (
        <els.Client
          key={key}
          module="./rail.tsx"
          width={width}
          height={1}
          props={{ active, width, color, dim: C.faint, marks, isMerge }}
        />
      ) : (
        <Text color={C.faint}>{'─'.repeat(Math.max(1, width))}</Text>
      )

    // A start time of 0 is unknown (state saved before it was recorded): no clock, not decades.
    const clock = (key: string, since: number, endAt: number | null, color: string) =>
      since <= 0 ? (
        <Text color={color}>—</Text>
      ) : hasClient ? (
        <els.Client key={key} module="./elapsed.tsx" props={{ since, now, endAt, color }} />
      ) : (
        <Text color={color}>{fmtTimer((endAt ?? now) - since)}</Text>
      )

    // ---- APEX: drawn only while a run is live, first and full width
    const alerts = alertsOf(apexRun, vd, bg)
    const shellsRunning = runningShells(sh)
    const doneShells = sh.filter(s => s.status !== 'running')
    const shownShells = [...sh.filter(s => s.status === 'running'), ...doneShells.slice(0, DONE_SHELLS)]
    const hiddenShells = sh.length - shownShells.length
    const markColor: Record<StepMark, string> = { done: C.apex, current: C.apex, pending: C.dim }
    const shellMark = (s: DeckApexShell) =>
      s.status === 'running'
        ? { glyph: '◐', color: C.agent }
        : s.status === 'completed'
          ? { glyph: '✓', color: C.ok }
          : s.status === 'failed'
            ? { glyph: '✗', color: C.warn }
            : { glyph: '■', color: C.dim }
    // A shell's row: mark, label, live duration (frozen once ended), status.
    const shellRow = (s: DeckApexShell, w: number) => {
      const sm = shellMark(s)
      return (
        <Box>
          <Text color={sm.color}>{`${sm.glyph} `}</Text>
          <Box width={Math.max(10, w - 24)}>
            <Text wrap="truncate">{s.label}</Text>
          </Box>
          <Text> </Text>
          <Box flexShrink={0}>{clock(`shell-clock-${s.id}`, s.startedAt, s.endedAt ?? null, C.dim)}</Box>
          <Text color={sm.color}>{` ${s.status}`}</Text>
        </Box>
      )
    }
    // The call clock and the task belong to the run the last Skill(apex) call started.
    const callRun = sr !== null && st.runKey === sessionKey(sr.startedAt) ? sr : null
    // At rest (main turn over, nothing of the run running): the clock stops, drawn as plain dim text.
    const restAt = callRun === null ? null : runEndedAt(callRun, cards, sh)
    const cells = stepCells(st)
    const detail = stepDetail(st)
    // A step cell is a Button (click, or Tab + Enter in the focused pane; no hotkey): it toggles
    // its explanation box, one open at a time. Written from the press, never from this render.
    const togglePress = (name: DeckApexStepName) => () => update($, openStep, x => (x === name ? null : name))
    const cellText = (c: StepCell) => (
      <Button key={`step-${c.name}`} plain onPress={togglePress(c.name)}>
        <Text color={c.isWarn ? C.warn : markColor[c.mark]} bold={c.mark === 'current' || c.name === open}>
          {`${PHASE_GLYPH[c.mark]} ${c.label}`}
        </Text>
      </Button>
    )
    // The live steps on one row (a separator Text between them, so each step reads on its own).
    const stepRow = () => cells.flatMap((c, i) => (i === 0 ? [cellText(c)] : [<Text>{'  '}</Text>, cellText(c)]))
    // The open step's explanation: its lines under the row, a running agent's with its live clock.
    const explain = open === null || !cells.some(c => c.name === open) ? null : explainStep(st, open)
    const explainRows = (max: number) =>
      explain === null
        ? []
        : explain.lines.slice(0, Math.max(0, max)).map((line, i) =>
            i === 0 && explain.since !== undefined ? (
              <Box>
                <Text color={C.dim} wrap="truncate">{`│ ${line} · `}</Text>
                <Box flexShrink={0}>{clock('explain-clock', explain.since, null, C.dim)}</Box>
              </Box>
            ) : (
              <Box>
                <Text color={C.faint}>{'│ '}</Text>
                <Text color={C.dim} wrap="truncate">
                  {line}
                </Text>
              </Box>
            ),
          )
    // `APEX · <branch> · <tier>`, then the time since the Skill(apex) call.
    const headerRow = (run: DeckApexRun) => (
      <Box>
        <Box flexShrink={1}>
          <Text color={C.apex} bold wrap="truncate">
            {apexHeader(run)}
          </Text>
        </Box>
        {callRun !== null ? <Text color={C.apex}>{' · '}</Text> : null}
        {callRun !== null ? (
          <Box flexShrink={0}>
            {restAt !== null ? <Text color={C.dim}>{fmtTimer(restAt - callRun.startedAt)}</Text> : clock('apex-clock', callRun.startedAt, null, C.apex)}
          </Box>
        ) : null}
      </Box>
    )
    const taskRow =
      callRun !== null && callRun.args !== '' ? (
        <Text color={C.dim} wrap="truncate">
          {callRun.args}
        </Text>
      ) : null
    // The current step's agent (with its live clock) or verdict.
    const detailRow =
      detail === null ? null : (
        <Box>
          <Text color={markColor[detail.mark]} wrap="truncate">
            {`${PHASE_GLYPH[detail.mark]} ${detail.text}${detail.since !== undefined ? ' ' : ''}`}
          </Text>
          {detail.since !== undefined ? <Box flexShrink={0}>{clock('step-clock', detail.since, null, C.dim)}</Box> : null}
        </Box>
      )
    const apexBlock = (w: number) => {
      if (apexRun === null) return null
      return (
        <Box flexDirection="column" width={w}>
          <Box flexDirection="column" borderStyle="round" borderColor={C.apex} paddingX={1} width={w}>
            {headerRow(apexRun)}
            {taskRow}
            <Box flexWrap="wrap" columnGap={2}>
              {cells.map(cellText)}
            </Box>
            {explainRows(explain?.lines.length ?? 0)}
            {detailRow}
            {alerts.map(al => (
              <Text color={C.warn} bold wrap="truncate">
                {alertText(al)}
              </Text>
            ))}
            {shownShells.map(s => shellRow(s, w))}
            {hiddenShells > 0 ? <Text color={C.faint}>{`+${hiddenShells} earlier shells`}</Text> : null}
          </Box>
          {rail('apex-link', m.isRunning || shellsRunning > 0, C.apex, w)}
        </Box>
      )
    }
    const apexRows =
      apexRun === null
        ? 0
        : 2 + 1 + (taskRow === null ? 0 : 1) + 1 + (explain?.lines.length ?? 0) + (detailRow === null ? 0 : 1) + alerts.length + shownShells.length + (hiddenShells > 0 ? 1 : 0) + 1

    // ---- main
    const effortN = { low: 1, medium: 2, high: 3, xhigh: 4, max: 4 }[m.effort] ?? 0
    const ctxGauge = u.pct !== null ? gauge(u.pct, 10) : null
    const mainPanel = (w: number) => (
      <Box flexDirection="column" borderStyle="round" borderColor={C.main} paddingX={1} width={w}>
        <Box justifyContent="space-between">
          <Text color={C.main} bold>
            {modelName} · main
          </Text>
          <Text color={m.isRunning ? C.main : C.dim}>{m.isRunning ? '● working' : '○ idle'}</Text>
        </Box>
        <Text wrap="truncate">
          <Text dimColor>effort </Text>
          <Text color={C.main}>{'▮'.repeat(effortN) + '▯'.repeat(4 - effortN)} </Text>
          <Text color={C.main} bold>
            {m.effort || '—'}
          </Text>
          {m.mode ? <Text dimColor>{`   mode ${m.mode}`}</Text> : null}
          <Text dimColor>{`   ${m.steps} req`}</Text>
        </Text>
        {ctxGauge ? (
          <Text wrap="truncate">
            <Text dimColor>ctx </Text>
            <Text color={u.pct !== null && u.pct >= 80 ? C.warn : C.main}>{ctxGauge.on}</Text>
            <Text color={C.faint}>{ctxGauge.off}</Text>
            <Text bold>{` ${Math.round(u.pct ?? 0)}%`}</Text>
            {u.tokens !== null ? <Text dimColor>{` ${kTokens(u.tokens)}/${kTokens(u.window)}`}</Text> : null}
            {u.compactions > 0 ? <Text color={C.amber}>{`  ⟲${u.compactions}`}</Text> : null}
          </Text>
        ) : null}
        {u.costUsd !== null || u.limits.length > 0 ? (
          <Text wrap="truncate">
            {u.costUsd !== null ? <Text color={C.text}>{`${fmtUsd(u.costUsd)}   `}</Text> : null}
            {u.limits.slice(0, 2).map(l => {
              const lg = gauge(l.pct, 5)
              return (
                <Text wrap="truncate">
                  <Text dimColor>{`${limitLabel(l.kind)} `}</Text>
                  <Text color={l.pct >= 80 ? C.warn : C.main}>{lg.on}</Text>
                  <Text color={C.faint}>{lg.off}</Text>
                  <Text dimColor>{` ${Math.round(l.pct)}%  `}</Text>
                </Text>
              )
            })}
          </Text>
        ) : null}
      </Box>
    )

    // ---- architect
    const lastConsult = a.consults[a.consults.length - 1]
    const architectPanel = (w: number) => {
      const tl = consultTimeline(a, now, Math.max(8, w - 4))
      return (
        <Box flexDirection="column" borderStyle="round" borderColor={C.arch} paddingX={1} width={w}>
          <Box justifyContent="space-between">
            <Text color={C.arch} bold>
              {cfg.architectLabel} · {advising ? 'advising' : 'on call'}
            </Text>
            <Text>
              <Text dimColor>consults </Text>
              <Text color={C.arch} bold>
                {a.consults.length}
              </Text>
            </Text>
          </Box>
          <Text color={C.arch}>{tl}</Text>
          {lastConsult ? (
            <Text dimColor wrap="truncate">
              {advising
                ? `consulting since ${fmtClock(lastConsult.at)}`
                : `last ${fmtDuration(now - (lastConsult.endAt ?? lastConsult.at))} ago · took ${fmtDuration((lastConsult.endAt ?? now) - lastConsult.at)}`}
            </Text>
          ) : (
            <Text dimColor>not consulted yet</Text>
          )}
          {cfg.moments ? (
            <Box flexWrap="wrap" columnGap={2}>
              {(['before a plan', 'error repeats', 'before done'] as const).map(mo => {
                const isOn = lastConsult?.moment === mo
                return (
                  <Text color={isOn ? C.arch : C.dim} bold={isOn}>
                    {isOn ? '◆' : '◇'} {mo}
                  </Text>
                )
              })}
              <Text color={C.faint}>(inferred)</Text>
            </Box>
          ) : null}
          {a.lastAdvice ? (
            <Text color={C.arch} wrap="truncate">
              » {a.lastAdvice}
            </Text>
          ) : null}
        </Box>
      )
    }

    // ---- agents: cards up to the limit, swimlanes beyond it
    const statusColor = (c: DeckAgentCard) => (c.status === 'failed' ? C.warn : c.status === 'done' ? C.ok : C.agent)
    const glyph = (c: DeckAgentCard) => (c.status === 'running' ? '◐' : c.status === 'done' ? '✓' : c.status === 'failed' ? '✗' : '■')
    const expandOnPress = (id: string) => () =>
      update($, view, x => ({ ...normalize(DEFAULT_VIEW, x), expanded: normalize(DEFAULT_VIEW, x).expanded === id ? null : id }))

    const agentsPanel = (w: number) => {
      // Cards need 20 columns each; when the pane can't hold the limit, lanes take over.
      const fit = Math.max(1, Math.min(cfg.maxCards, Math.floor((w + 1) / 21)))
      const useLanes = cards.length > fit
      const header = (
        <Box justifyContent="space-between" width={w}>
          <Text bold>{`agents · ${running.length} running · ${cards.length} total`}</Text>
          {cards.length > 0 ? <Text color={C.faint}>1-{Math.min(cards.length, useLanes ? 6 : fit)} expand</Text> : null}
        </Box>
      )
      if (cards.length === 0) {
        return (
          <Box flexDirection="column" width={w}>
            {header}
            <Text color={C.faint}>no subagents yet</Text>
          </Box>
        )
      }
      if (useLanes) {
        const shown = cards.slice(-6)
        const barW = Math.max(8, w - 28)
        const geo = lanes(shown, now, barW)
        return (
          <Box flexDirection="column" width={w}>
            {header}
            {cards.length > shown.length ? <Text color={C.faint}>{`+${cards.length - shown.length} earlier`}</Text> : null}
            {shown.map((c, i) => {
              const gm = geo[i]
              const isViewed = viewed === c.id
              return (
                <Box>
                  <Text color={statusColor(c)} bold={isViewed}>{`${isViewed ? '▶' : glyph(c)} `}</Text>
                  <Box width={17}>
                    <Button key={`card-${c.id}`} plain hotkey={String(i + 1)} label={shorten(cardTitle(c), 14)} onPress={expandOnPress(c.id)} />
                  </Box>
                  <Text color={C.faint}>{' ' + '·'.repeat(gm?.before ?? 0)}</Text>
                  <Text color={statusColor(c)}>{'━'.repeat(gm?.bar ?? 1)}</Text>
                  <Text color={C.faint}>{'·'.repeat(gm?.after ?? 0) + ' '}</Text>
                  {clock(`lane-clock-${c.id}`, c.spawnedAt, c.endedAt, C.dim)}
                </Box>
              )
            })}
          </Box>
        )
      }
      const shown = cards.slice(-fit)
      const cardW = Math.max(20, Math.floor((w - (shown.length - 1)) / shown.length))
      const centers = shown.map((_, i) => i * (cardW + 1) + Math.floor(cardW / 2))
      return (
        <Box flexDirection="column" width={w}>
          {header}
          {rail('fan-out', running.length > 0, C.agent, w, centers)}
          <Box columnGap={1}>
            {shown.map((c, i) => {
              const isViewed = viewed === c.id
              const sameModel = !c.model || prettyModel(c.model) === modelName
              return (
                <Box
                  flexDirection="column"
                  borderStyle={isViewed ? 'double' : 'round'}
                  borderColor={c.lastStop === 'max_tokens' ? C.warn : C.agent}
                  borderDimColor={c.status !== 'running' && !isViewed}
                  width={cardW}
                  paddingX={1}
                >
                  <Button key={`card-${c.id}`} plain hotkey={String(i + 1)} label={titleLines(cardTitle(c), cardW - 7, cardW - 4)[0]} onPress={expandOnPress(c.id)} />
                  <Text bold wrap="truncate">
                    {titleLines(cardTitle(c), cardW - 7, cardW - 4)[1]}
                  </Text>
                  <Text color={C.dim} wrap="truncate">
                    {sameModel ? c.type : `${c.type} · ${prettyModel(c.model)}`}
                  </Text>
                  <Text dimColor wrap="truncate">
                    {c.steps > 0 ? `ctx ${kTokens(c.ctx)} · out ${kTokens(c.out)} · ${c.steps} st` : 'starting…'}
                  </Text>
                  <Box>
                    <Text color={c.lastStop === 'max_tokens' ? C.warn : statusColor(c)}>
                      {cardW >= 26 ? `${glyph(c)} ${c.lastStop === 'max_tokens' ? 'max_tokens' : c.status} ` : `${glyph(c)} `}
                    </Text>
                    <Box flexShrink={0}>{clock(`card-clock-${c.id}`, c.spawnedAt, c.endedAt, C.dim)}</Box>
                  </Box>
                </Box>
              )
            })}
          </Box>
          {rail('merge', running.length > 0, C.agent, w, centers, true)}
        </Box>
      )
    }

    const expandedCard = cards.find(c => c.id === v.expanded)
    const expandedPanel = (w: number) =>
      expandedCard ? (
        <Box flexDirection="column" borderStyle="single" borderColor={C.agent} paddingX={1} width={w}>
          <Text bold wrap="wrap">
            {expandedCard.description || expandedCard.type}
          </Text>
          <Text dimColor wrap="truncate">{`${expandedCard.type} · ${prettyModel(expandedCard.model)} · ${expandedCard.status} · ${expandedCard.steps} steps`}</Text>
          {expandedCard.tools.length === 0 ? <Text color={C.faint}>no tool calls yet</Text> : null}
          {expandedCard.tools.map(n => (
            <Text color={n.isError ? C.warn : C.text} wrap="truncate">
              {`${n.isError ? '✗' : '·'} ${n.text}`}
            </Text>
          ))}
          {expandedCard.answer ? (
            <Text dimColor wrap="wrap">
              {`» ${shorten(expandedCard.answer, 240)}`}
            </Text>
          ) : null}
        </Box>
      ) : null

    // ---- receipt: the turn now, or the last one
    const receiptPanel = (w: number) => {
      const isReview = t.isReviewing
      return (
        <Box flexDirection="column" borderStyle="round" borderColor={C.main} borderDimColor={!m.isRunning && !isReview} paddingX={1} width={w}>
          {m.isRunning ? (
            <Box>
              <Text color={C.main} wrap="truncate">{`◐ back to ${modelName.toLowerCase()} · turn `}</Text>
              <Box flexShrink={0}>{clock('turn-clock', t.startedAt, null, C.main)}</Box>
              {w >= 60 ? <Text dimColor wrap="truncate">{` · ${plural(t.edits, 'edit')} · ${plural(t.errors, 'error')}`}</Text> : null}
            </Box>
          ) : r ? (
            <Text wrap="truncate">
              <Text color={r.reason === 'answer' ? C.ok : C.warn}>{r.reason === 'answer' ? '✓ ' : '✗ '}</Text>
              <Text>{`last turn ${fmtDuration(r.durationMs)} · ${plural(r.agents, 'agent')} · ${plural(r.edits, 'edit')} · ${plural(r.errors, 'error')}`}</Text>
              {r.costDelta !== null ? <Text color={C.main}>{` · +${fmtUsd(r.costDelta)}`}</Text> : null}
            </Text>
          ) : (
            <Text color={C.faint}>no turn finished yet</Text>
          )}
          {isReview ? <Text color={C.arch}>{`${cfg.architectLabel.toLowerCase()} reviewing before done (inferred)`}</Text> : null}
        </Box>
      )
    }

    // ---- log: whatever rows the other panels leave, 4 to 8
    const used = 2 + apexRows + 5 + (showArchitect ? 6 : 0) + (cards.length > cfg.maxCards ? 3 + Math.min(6, cards.length) : 8) + (expandedCard ? 8 : 0) + 3
    const bodyRows = e.props.scroll?.bodyRows ?? e.viewport?.rows ?? 40
    const nLog = logRows(bodyRows, used)
    const shownLines = (viewed ? lines.filter(l => l.agentId === viewed) : lines).slice(-nLog)
    const colorOf = (l: DeckLogLine) =>
      l.kind === 'error'
        ? C.warn
        : l.kind === 'consult'
          ? C.arch
          : l.who === 'apex'
            ? C.apex
            : l.who === 'main'
              ? C.main
              : l.who === 'you'
                ? C.text
                : C.agent
    const logPanel = (w: number) => (
      <Box flexDirection="column" borderStyle="round" borderColor={C.faint} paddingX={1} width={w}>
        <Text dimColor>{viewed ? 'session log · this agent' : 'session log'}</Text>
        {shownLines.length === 0 ? <Text color={C.faint}>nothing yet</Text> : null}
        {shownLines.map(l => (
          <Box>
            <Box width={9} flexShrink={0}>
              <Text color={C.faint}>{fmtClock(l.at)}</Text>
            </Box>
            <Box width={13} flexShrink={0}>
              <Text color={colorOf(l)} bold wrap="truncate">
                {l.who}
              </Text>
            </Box>
            <Text color={l.kind === 'error' ? C.warn : C.text} wrap="truncate">
              {l.text}
            </Text>
          </Box>
        ))}
      </Box>
    )

    const draw = (p: Panel, w: number) =>
      p === 'main' ? mainPanel(w) : p === 'architect' ? architectPanel(w) : p === 'agents' ? agentsPanel(w) : p === 'receipt' ? receiptPanel(w) : logPanel(w)

    // Panels with the flow between them; the agents panel draws its own rails.
    const column = (ps: Panel[], w: number) => (
      <Box flexDirection="column" width={w}>
        {ps.map((p, i) => {
          const prev = ps[i - 1]
          const link =
            i === 0 || p === 'agents' || prev === 'agents' || p === 'log'
              ? null
              : rail(`link-${p}`, p === 'architect' ? advising : m.isRunning, p === 'architect' ? C.arch : C.main, w)
          return (
            <Box flexDirection="column">
              {link}
              {draw(p, w)}
              {p === 'agents' ? expandedPanel(w) : null}
            </Box>
          )
        })}
      </Box>
    )

    // Desktop draws the agents' time axis as SVG under the panels.
    const svgLanes =
      e.surface !== 'terminal' && cards.length > 0
        ? (() => {
            const { Svg } = $.ui.resolve(e)
            const rowH = 18
            const pxW = 520
            const geo = lanes(cards.slice(-10), now, 100)
            const rects = cards
              .slice(-10)
              .map((c, i) => {
                const gm = geo[i]
                const x = 150 + ((gm?.before ?? 0) / 100) * (pxW - 160)
                const wpx = Math.max(3, ((gm?.bar ?? 1) / 100) * (pxW - 160))
                const fill = c.status === 'running' ? SVG_COLORS.running : c.status === 'done' ? SVG_COLORS.done : c.status === 'failed' ? SVG_COLORS.failed : SVG_COLORS.other
                const label = shorten(cardTitle(c), 22).replace(/[<&>]/g, '')
                return `<text x="4" y="${i * rowH + 13}" font-size="11" fill="${SVG_COLORS.label}">${label}</text><rect x="${x}" y="${i * rowH + 4}" width="${wpx}" height="10" rx="3" fill="${fill}"/>`
              })
              .join('')
            const svgH = Math.min(10, cards.length) * rowH + 4
            return (
              <Svg
                source={`<svg xmlns="http://www.w3.org/2000/svg" width="${pxW}" height="${svgH}" viewBox="0 0 ${pxW} ${svgH}">${rects}</svg>`}
                alt={`${cards.length} agents on a time axis`}
                width={pxW}
                height={svgH}
              />
            )
          })()
        : null

    // Inline above the prompt (the terminal's main screen), the pane is a summary of at most 8 rows.
    const isMini = layout === 'mini' || (layout === 'auto' && e.props.placement === 'inline')
    if (isMini) {
      const MINI_ROWS = 8
      const mg = u.pct !== null ? gauge(u.pct, 6) : null
      // While a run is live it takes its rows first: header, task, step row, its detail, each
      // alert, the running shells; the agents and the receipt get what is left of the 8.
      const apexRest =
        apexRun === null
          ? []
          : [
              ...(detailRow === null ? [] : [detailRow]),
              ...alerts.map(al => (
                <Text color={C.warn} bold wrap="truncate">
                  {alertText(al)}
                </Text>
              )),
              ...sh.filter(s => s.status === 'running').map(s => shellRow(s, W)),
            ]
      const apexHead = apexRun === null ? [] : [headerRow(apexRun), ...(taskRow === null ? [] : [taskRow])]
      // The open explanation takes the agents' rows first: at most 3, and at least 1 while the
      // run's other rows leave none.
      const explainN = Math.min(3, explain?.lines.length ?? 0, Math.max(1, MINI_ROWS - 1 - apexHead.length - 1 - apexRest.length))
      const apexMini =
        apexRun === null
          ? []
          : [...apexHead, <Box overflow="hidden">{stepRow()}</Box>, ...explainRows(explainN), ...apexRest].slice(0, MINI_ROWS - 1)
      const room = MINI_ROWS - 1 - apexMini.length
      const ordered = [...cards.filter(c => c.status === 'running'), ...cards.filter(c => c.status !== 'running').reverse()]
      let nLive = Math.min(3, cards.length, room)
      // Agents left out: their « +N more » row takes the last slot.
      if (cards.length > nLive && nLive > 0 && nLive === room) nLive -= 1
      const live = ordered.slice(0, nLive)
      const showMore = cards.length > live.length && room > live.length
      const showReceipt = !m.isRunning && r !== null && room - live.length - (showMore ? 1 : 0) > 0
      return (
        <Box flexDirection="column" width={W}>
          <Text wrap="truncate">
            <Text color={C.main} bold>
              {modelName}
            </Text>
            <Text color={m.isRunning ? C.main : C.dim}>{m.isRunning ? ' ● working' : ' ○ idle'}</Text>
            {mg ? <Text dimColor> · ctx </Text> : null}
            {mg ? <Text color={(u.pct ?? 0) >= 80 ? C.warn : C.main}>{mg.on}</Text> : null}
            {mg ? <Text color={C.faint}>{mg.off}</Text> : null}
            {mg ? <Text>{` ${Math.round(u.pct ?? 0)}%`}</Text> : null}
            {u.compactions > 0 ? <Text color={C.amber}>{` ⟲${u.compactions}`}</Text> : null}
            {u.costUsd !== null ? <Text dimColor>{` · ${fmtUsd(u.costUsd)}`}</Text> : null}
            {showArchitect ? <Text color={C.arch}>{` · ${cfg.architectLabel.toLowerCase()} ${advising ? 'advising' : a.consults.length}`}</Text> : null}
          </Text>
          {apexMini}
          {live.map(c => (
            <Box>
              <Text color={statusColor(c)}>{`${glyph(c)} `}</Text>
              <Box width={Math.max(10, W - 30)}>
                <Text wrap="truncate">{cardTitle(c)}</Text>
              </Box>
              <Text dimColor>{c.steps > 0 ? ` ctx ${kTokens(c.ctx)} ` : ' '}</Text>
              {clock(`mini-clock-${c.id}`, c.spawnedAt, c.endedAt, C.dim)}
            </Box>
          ))}
          {showMore ? (
            <Text color={C.faint} wrap="truncate">{`+${cards.length - live.length} more agents · /deck layout compact for all`}</Text>
          ) : null}
          {showReceipt && r ? (
            <Text dimColor wrap="truncate">
              {`last turn ${fmtDuration(r.durationMs)} · ${plural(r.agents, 'agent')} · ${plural(r.edits, 'edit')} · ${plural(r.errors, 'error')}${r.costDelta !== null ? ` · +${fmtUsd(r.costDelta)}` : ''}`}
            </Text>
          ) : null}
        </Box>
      )
    }

    const legend = fitLegend(
      [
        ...(apexRun !== null ? [{ label: 'apex', color: C.apex }] : []),
        { label: 'main', color: C.main },
        { label: 'agents', color: C.agent },
        ...(showArchitect ? [{ label: cfg.architectLabel.toLowerCase(), color: C.arch }] : []),
      ],
      W,
    )

    const body = isWide ? (
      <Box flexDirection="column">
        <Box columnGap={2}>
          {column(panels.filter(p => p === 'main' || p === 'architect'), colW)}
          {column(panels.filter(p => p === 'agents' || p === 'receipt'), colW)}
        </Box>
        {panels.includes('log') ? logPanel(W) : null}
      </Box>
    ) : (
      column(panels, W)
    )

    return (
      <Box flexDirection="column" width={W}>
        <Box justifyContent="center">
          <Text bold wrap="truncate">
            <Text>DECK</Text>
            <Text color={C.dim}> · </Text>
            <Text color={C.main}>{modelName.toUpperCase()}</Text>
            <Text>{m.isRunning ? ' WORKS' : ' IDLE'}</Text>
            {showArchitect ? <Text color={C.dim}> · </Text> : null}
            {showArchitect ? <Text color={C.arch}>{cfg.architectLabel}</Text> : null}
            {showArchitect ? <Text>{advising ? ' ADVISING' : ' ON CALL'}</Text> : null}
          </Text>
        </Box>
        <Box justifyContent="center" columnGap={2}>
          {legend.map(l => (
            <Text>
              <Text color={l.color}>■</Text>
              <Text dimColor>{` ${l.label}`}</Text>
            </Text>
          ))}
        </Box>
        {apexBlock(W)}
        {body}
        {svgLanes}
      </Box>
    )
  })
}

files.hooks/core.ts:
// Pure data: defaults, reducers, formatting and layout math. Nothing here touches `$`, so every
// behaviour is testable directly (the test kit cannot raise a subagent's tool call; these
// functions are what the hooks apply). From Flightdeck v0.3.2 (MIT, Stephen Casella).
import type {
  DeckAgentCard,
  DeckArchitect,
  DeckLayout,
  DeckLogLine,
  DeckMain,
  DeckMoment,
  DeckReceipt,
  DeckRoster,
  DeckToolNote,
  DeckTurn,
  DeckUsage,
  DeckView,
} from '../types'

// ---------------------------------------------------------------- defaults

export const DEFAULT_MAIN: DeckMain = { model: '', effort: '', mode: '', steps: 0, isRunning: false }
export const DEFAULT_USAGE: DeckUsage = {
  pct: null,
  tokens: null,
  window: 0,
  costUsd: null,
  limits: [],
  compactions: 0,
  lastCompactAt: null,
}
export const DEFAULT_ARCHITECT: DeckArchitect = { consults: [], ids: [], seen: [], lastAdvice: '' }
export const DEFAULT_TURN: DeckTurn = { edits: 0, errorStreak: 0, errors: 0, isReviewing: false, startedAt: 0, costAtStart: null }
export const DEFAULT_VIEW: DeckView = { expanded: null, layout: null }
export const DEFAULT_ROSTER: DeckRoster = { architectTypes: [] }

const isObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)

/** A stored object merged over its defaults, so a value saved under an older shape still reads. */
export const normalize = <T extends object>(def: T, stored: unknown): T =>
  isObject(stored) ? ({ ...def, ...stored } as T) : def

/** A stored list, or empty when what is stored is not a list. */
export const listOf = <T>(stored: unknown): T[] => (Array.isArray(stored) ? (stored as T[]) : [])

export const normalizeCard = (stored: unknown): DeckAgentCard =>
  normalize<DeckAgentCard>(
    {
      id: '',
      type: 'agent',
      model: '',
      description: '',
      status: 'running',
      spawnedAt: 0,
      endedAt: null,
      ctx: 0,
      out: 0,
      steps: 0,
      lastStop: null,
      tools: [],
      answer: '',
    },
    stored,
  )

export const normalizeLog = (stored: unknown): DeckLogLine[] =>
  listOf<Record<string, unknown>>(stored).map(l => ({
    at: typeof l.at === 'number' ? l.at : 0,
    who: String(l.who ?? ''),
    text: String(l.text ?? ''),
    agentId: typeof l.agentId === 'string' ? l.agentId : null,
    kind: l.kind === 'error' || l.kind === 'consult' || l.kind === 'done' ? l.kind : 'info',
  }))

// ---------------------------------------------------------------- config

export type Panel = 'main' | 'architect' | 'agents' | 'receipt' | 'log'
const PANELS: readonly Panel[] = ['main', 'architect', 'agents', 'receipt', 'log']

export type Config = {
  architect: RegExp
  architectLabel: string
  panels: Panel[]
  motion: boolean
  moments: boolean
  matchDescriptions: boolean
  maxCards: number
  layout: DeckLayout
  palette: Palette
}

const safeRegExp = (source: string, fallback: string) => {
  try {
    return new RegExp(source || fallback, 'i')
  } catch {
    return new RegExp(fallback, 'i')
  }
}

/** The plugin's `/config` values, read leniently: anything malformed falls back to the default. */
export const parseConfig = (o: Readonly<Record<string, unknown>>): Config => {
  const str = (k: string, d: string) => (typeof o[k] === 'string' && o[k] !== '' ? (o[k] as string) : d)
  const bool = (k: string, d: boolean) => (typeof o[k] === 'boolean' ? (o[k] as boolean) : d)
  const panels = str('panels', PANELS.join(','))
    .split(',')
    .map(s => s.trim())
    .filter((p): p is Panel => (PANELS as readonly string[]).includes(p))
  const layout = str('layout', 'auto')
  const max = typeof o.maxCards === 'number' ? Math.round(o.maxCards) : 3
  return {
    architect: safeRegExp(str('architectPattern', ''), 'advisor|architect'),
    architectLabel: str('architectLabel', 'ARCHITECT'),
    panels: panels.length > 0 ? [...new Set(panels)] : [...PANELS],
    motion: str('motion', 'while-active') !== 'off',
    moments: bool('moments', true),
    matchDescriptions: bool('matchDescriptions', false),
    maxCards: Math.min(6, Math.max(1, max)),
    layout: layout === 'compact' || layout === 'wide' || layout === 'mini' ? layout : 'auto',
    palette: str('palette', 'theme') === 'pastel' ? 'pastel' : 'theme',
  }
}

// ---------------------------------------------------------------- palette

export type Palette = 'theme' | 'pastel'
export type Colors = Record<'main' | 'agent' | 'ok' | 'arch' | 'apex' | 'amber' | 'warn' | 'dim' | 'faint' | 'text', string>

/**
 * `theme` names the person's own theme colours (they follow light, dark and colour-blind themes);
 * `pastel` is fixed hex tuned for dark terminals.
 */
export const PALETTES: Record<Palette, Colors> = {
  theme: {
    main: 'claude',
    agent: 'suggestion',
    ok: 'success',
    arch: 'merged',
    apex: 'planMode',
    amber: 'warning',
    warn: 'error',
    dim: 'inactive',
    faint: 'subtle',
    text: 'text',
  },
  pastel: {
    main: '#7dd3fc',
    agent: '#93c5fd',
    ok: '#86efac',
    arch: '#c4b5fd',
    apex: '#fdba74',
    amber: '#fcd34d',
    warn: '#fca5a5',
    dim: '#6b7280',
    faint: '#3f4654',
    text: '#e5e7eb',
  },
}

/** SVG cannot name theme keys: mid-tone colours that read on light and dark backgrounds. */
export const SVG_COLORS = { running: '#3b82f6', done: '#16a34a', failed: '#dc2626', other: '#8b5cf6', label: '#6b7280' }

// ---------------------------------------------------------------- formatting

/**
 * A model id as people say it, from any provider's spelling: `claude-opus-5-5[1m]` → `Opus 5.5 1M`,
 * `us.anthropic.claude-sonnet-4-5-20250929-v1:0` → `Sonnet 4.5`, `claude-3-5-haiku-20241022` →
 * `Haiku 3.5`. Anything else is shown as given, cut to 22 characters.
 */
export const prettyModel = (id: string) => {
  if (!id) return '—'
  const cap = (f: string) => f.charAt(0).toUpperCase() + f.slice(1)
  const big = /\[1m\]|-1m\b/i.test(id) ? ' 1M' : ''
  const now = /claude-([a-z]+)-(\d+)(?:-(\d{1,2}))?(?:-\d{8})?(?![\d])/i.exec(id)
  if (now?.[1] && !/^\d/.test(now[1])) return `${cap(now[1].toLowerCase())} ${now[2]}${now[3] ? `.${now[3]}` : ''}${big}`
  const old = /claude-(\d+)(?:-(\d))?-([a-z]+)/i.exec(id)
  if (old?.[3]) return `${cap(old[3].toLowerCase())} ${old[1]}${old[2] ? `.${old[2]}` : ''}${big}`
  return shorten(id, 22)
}

export const shorten = (s: string, n: number) => {
  const one = s.replace(/\s+/g, ' ').trim()
  return n <= 0 ? '' : one.length > n ? `${one.slice(0, Math.max(0, n - 1)).trimEnd()}…` : one
}

export const kTokens = (n: number) =>
  n >= 1_000_000 ? `${(n / 1_000_000).toFixed(1)}M` : n >= 1000 ? `${Math.round(n / 1000)}k` : String(n)

export const fmtDuration = (ms: number) => {
  const s = Math.max(0, Math.round(ms / 1000))
  if (s < 60) return `${s}s`
  const m = Math.floor(s / 60)
  return m < 60 ? `${m}m${String(s % 60).padStart(2, '0')}s` : `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}m`
}

/** A running clock as the live cards draw it: m:ss, or XhYY past an hour. */
export const fmtTimer = (ms: number) => {
  const s = Math.max(0, Math.floor(ms / 1000))
  const m = Math.floor(s / 60)
  return m < 60 ? `${m}:${String(s % 60).padStart(2, '0')}` : `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}`
}

export const fmtClock = (ms: number) => (ms > 0 ? new Date(ms).toTimeString().slice(0, 8) : '--:--:--')

/** `1 error`, `2 errors`. */
export const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? '' : 's'}`

export const fmtUsd = (n: number) => (n >= 100 ? `$${Math.round(n)}` : `$${n.toFixed(2)}`)

/** A gauge of `width` cells: ▰ filled, ▱ empty. */
export const gauge = (pct: number, width: number) => {
  const full = Math.max(0, Math.min(width, Math.round((pct / 100) * width)))
  return { on: '▰'.repeat(full), off: '▱'.repeat(width - full) }
}

/** A rate-limit window's short name: `five_hour` → `5h`, `seven_day_opus` → `7d opus`. */
export const limitLabel = (kind: string) =>
  kind
    .replace(/five[_ -]?hours?/i, '5h')
    .replace(/seven[_ -]?days?/i, '7d')
    .replace(/[_-]+/g, ' ')
    .trim()

// ---------------------------------------------------------------- redaction

const SECRETS: [RegExp, string][] = [
  [/(authorization\s*[:=]\s*)(bearer\s+|basic\s+)?\S+/gi, '$1$2•••'],
  [/\b(bearer)\s+[A-Za-z0-9._~+/-]{8,}=*/gi, '$1 •••'],
  [/\b(sk|pk|rk|ghp|gho|ghs|github_pat|xox[abprs])[-_][A-Za-z0-9_-]{8,}/g, '•••'],
  [/((?:api[_-]?key|access[_-]?token|token|secret|password|passwd|pwd)\s*[=:]\s*)("[^"]*"|'[^']*'|\S+)/gi, '$1•••'],
  [/(--(?:token|password|api-key|secret)[= ])\S+/gi, '$1•••'],
  [/(\b[A-Z][A-Z0-9_]*(?:KEY|TOKEN|SECRET|PASSWORD)=)\S+/g, '$1•••'],
  [/(\b[a-z][a-z0-9+.-]*:\/\/[^\s/:@]+:)[^\s@]+@/gi, '$1•••@'],
]

/** What the log and the cards may store: credentials masked before anything is written to state. */
export const redact = (s: string) => SECRETS.reduce((t, [re, to]) => t.replace(re, to), s)

// ---------------------------------------------------------------- tools

export const EDIT_TOOLS = new Set(['Edit', 'Write', 'NotebookEdit'])

/** One line saying what a call was about: its command, path or pattern; redacted. */
export const describeInput = (tool: string, input: unknown) => {
  const i = isObject(input) ? input : {}
  const path = typeof i.file_path === 'string' ? i.file_path.split(/[\\/]/).slice(-2).join('/') : ''
  const what =
    typeof i.command === 'string'
      ? i.command
      : path || (typeof i.pattern === 'string' ? i.pattern : typeof i.url === 'string' ? i.url : typeof i.description === 'string' ? i.description : '')
  return redact(what ? `${tool} → ${what}` : tool)
}

// ---------------------------------------------------------------- turn and architect

/**
 * The turn after one tool call. Errors count in the main loop only (a subagent's failure is its
 * own); edits count from every loop, so delegated work still reaches "before done".
 */
export const afterCall = (t: DeckTurn, c: { inSubagent: boolean; hasFailed: boolean; isEdit: boolean }): DeckTurn => ({
  ...t,
  errorStreak: c.inSubagent ? t.errorStreak : c.hasFailed ? t.errorStreak + 1 : 0,
  errors: t.errors + (!c.inSubagent && c.hasFailed ? 1 : 0),
  edits: t.edits + (c.isEdit ? 1 : 0),
})

/** Which of the architect's three moments a consult falls at: an inference over this turn so far. */
export const momentOf = (t: Pick<DeckTurn, 'edits' | 'errorStreak'>): DeckMoment =>
  t.errorStreak >= 2 ? 'error repeats' : t.edits === 0 ? 'before a plan' : 'before done'

export const startConsult = (a: DeckArchitect, c: { id: string; at: number; moment: DeckMoment; via: string }): DeckArchitect =>
  a.consults.some(x => x.id === c.id) ? a : { ...a, consults: [...a.consults, { ...c, endAt: null }].slice(-40) }

/** Ends the open consult (the latest without an end), or the one named. */
export const endConsult = (a: DeckArchitect, at: number, advice: string | null, id?: string): DeckArchitect => {
  const open = [...a.consults].reverse().find(c => c.endAt === null && (id === undefined || c.id === id))
  return {
    ...a,
    consults: a.consults.map(c => (c === open ? { ...c, endAt: at } : c)),
    lastAdvice: advice ?? a.lastAdvice,
  }
}

export const isAdvising = (a: DeckArchitect) => a.consults.some(c => c.endAt === null)

/** A one-row timeline of consults across `width` cells: ◆ a consult, ━ while it ran. */
export const consultTimeline = (a: DeckArchitect, now: number, width: number) => {
  if (a.consults.length === 0 || width < 4) return '─'.repeat(Math.max(0, width))
  const first = a.consults[0]?.at ?? now
  const span = Math.max(1, now - first)
  const cells = Array.from({ length: width }, () => '─')
  for (const c of a.consults) {
    const from = Math.min(width - 1, Math.floor(((c.at - first) / span) * (width - 1)))
    const to = Math.min(width - 1, Math.floor((((c.endAt ?? now) - first) / span) * (width - 1)))
    for (let i = from + 1; i <= to; i += 1) cells[i] = '━'
    cells[from] = '◆'
  }
  return cells.join('')
}

export const receiptOf = (t: DeckTurn, o: { durationMs: number; agentsSince: number; costNow: number | null; reason: string }): DeckReceipt => ({
  durationMs: o.durationMs,
  agents: o.agentsSince,
  edits: t.edits,
  errors: t.errors,
  costDelta: o.costNow !== null && t.costAtStart !== null && o.costNow - t.costAtStart >= 0.005 ? o.costNow - t.costAtStart : null,
  reason: o.reason,
})

// ---------------------------------------------------------------- agents

type StepUsage = { input_tokens?: number; cache_read_input_tokens?: number; cache_creation_input_tokens?: number; output_tokens?: number } | null

/** A card after one of its model requests: its context is the latest step's whole input; output adds up. */
export const applyStep = (c: DeckAgentCard, s: { model: string; usage: StepUsage; stopReason: string | null }): DeckAgentCard => {
  const u = s.usage ?? {}
  const ctx = (u.input_tokens ?? 0) + (u.cache_read_input_tokens ?? 0) + (u.cache_creation_input_tokens ?? 0)
  return {
    ...c,
    model: c.model || s.model,
    steps: c.steps + 1,
    ctx: ctx > 0 ? ctx : c.ctx,
    out: c.out + (u.output_tokens ?? 0),
    lastStop: s.stopReason,
  }
}

export const noteTool = (c: DeckAgentCard, n: DeckToolNote): DeckAgentCard => ({ ...c, tools: [...c.tools, n].slice(-3) })

/** Swimlane geometry: each agent's bar on one shared axis from the first spawn to now. */
export const lanes = (cards: DeckAgentCard[], now: number, width: number) => {
  const start = Math.min(...cards.map(c => c.spawnedAt).filter(n => n > 0), now)
  const span = Math.max(1, now - start)
  return cards.map(c => {
    const from = Math.floor(((Math.max(c.spawnedAt, start) - start) / span) * width)
    const to = Math.max(from + 1, Math.ceil((((c.endedAt ?? now) - start) / span) * width))
    return { id: c.id, before: Math.min(from, width), bar: Math.min(to, width) - Math.min(from, width), after: width - Math.min(to, width) }
  })
}

// ---------------------------------------------------------------- layout

/** How many log lines fit: what the other panels leave, never fewer than 4 nor more than 8. */
export const logRows = (bodyRows: number, used: number) => Math.max(4, Math.min(8, bodyRows - used - 3))

/** Legend items that fit on one row of `width` cells, in order; the rest are dropped. */
export const fitLegend = <T extends { label: string }>(items: T[], width: number) => {
  const out: T[] = []
  let used = 0
  for (const it of items) {
    const w = it.label.length + 4
    if (used + w > width) break
    out.push(it)
    used += w
  }
  return out
}

/** A card's title row: the task in the agent's own words, the type only when there is none. */
export const cardTitle = (c: DeckAgentCard) => c.description || c.type

/** A title split over two rows at a word boundary: `first` cells on row one, `rest` on row two. */
export const titleLines = (title: string, first: number, rest: number): [string, string] => {
  const t = title.replace(/\s+/g, ' ').trim()
  if (t.length <= first) return [t, '']
  const cut = t.lastIndexOf(' ', first)
  const at = cut > 0 ? cut : first
  return [t.slice(0, at).trim(), shorten(t.slice(at), rest)]
}

/**
 * What a turn's opening text was, for the log: the person's words, or for a turn the engine
 * opened with a tagged message (a subagent's hand-back, a task notification), that message's kind.
 */
export const promptLine = (text: string): { who: string; text: string } => {
  const tag = /^\s*<([a-z][\w-]*)/i.exec(text)?.[1]
  if (!tag) return { who: 'you', text: shorten(text, 70) }
  const from = /\bfrom="([^"]+)"/.exec(text)?.[1]
  return { who: 'engine', text: shorten(`${tag.replace(/[-_]/g, ' ')}${from ? ` from ${from.slice(0, 8)}` : ''}`, 70) }
}

/**
 * A subagent's hand-back message: who sent it and the first line of what it said. The report
 * follows a framing header in the message; without one, the first line after the opening tag.
 */
export const handbackOf = (text: string): { from: string; body: string } | null => {
  const from = /^\s*<agent-message\s+from="([^"]+)"/.exec(text)?.[1]
  if (!from) return null
  const afterHeader = text.split(/The report follows:\s*\n/)[1]
  const rest = afterHeader ?? text.replace(/^\s*<agent-message[^>]*>/, '')
  const body =
    rest
      .split('\n')
      .map(l => l.trim())
      .find(l => l && !l.startsWith('[') && !l.startsWith('<') && !l.startsWith('</')) ?? ''
  return body ? { from, body } : null
}

/** The advice line a pane shows for a report: its first real line, markdown markers stripped, cut to 160. */
export const adviceLine = (report: string) => {
  const first = report.split('\n').map(l => l.trim()).find(l => l && !l.startsWith('[') && !l.startsWith('<')) ?? ''
  return shorten(first.replace(/\*\*|__/g, '').replace(/^[#>*\s-]+/, ''), 160)
}

export const elapsedOf = (c: DeckAgentCard, now: number) => (c.endedAt ?? now) - c.spawnedAt

files.hooks/apex.ts:
// Pure reading of an APEX run: its 00-context.md (header and Progress table, every drifted
// spelling tolerated), its liveness rule, the live steps its tool calls stand for, the external
// verdict file, and what the block and the log show of it. No `$`, no clock, no I/O.

import type {
  DeckApexLiveStep,
  DeckApexRun,
  DeckApexSessionRun,
  DeckApexStep,
  DeckApexStepKind,
  DeckApexStepName,
  DeckApexSteps,
} from '../types'
import { fmtTimer, shorten } from './core'

// ---------------------------------------------------------------- context file

/** A run is live only while its context file moved in the last 6 hours. */
export const STALE_MS = 6 * 60 * 60 * 1000

const clean = (value: string): string => value.replace(/\*\*/g, '').replace(/`/g, '').trim()

export function statusKind(status: string): DeckApexStepKind {
  const s = clean(status).toLowerCase()
  if (/^(complete|done|✅)/.test(s)) return 'done'
  if (/^pending/.test(s)) return 'pending'
  if (/^(in[ _]progress|en cours|running)/.test(s)) return 'running'
  if (/^(skipped|supprimé|n\/a)/.test(s)) return 'skipped'
  if (/^(red|failed|échoué)(?![a-z])/.test(s)) return 'failed'
  return 'other'
}

// "Key: value", "**Key:** value", "**Key**: value", "- Key: value".
const FIELD = /^\s*(?:[-*]\s+)?\**\s*([A-Za-zÀ-ÿ][A-Za-zÀ-ÿ ]*?)\s*\**\s*:\s*(.*)$/

/** A header value's head: `Standard (mods UI) — files…` → `Standard`. */
function headOf(value: string): string {
  const head = value.split(/\s+—\s+|\s+→\s+|\s*\(|;|\.\s/)[0] ?? value
  return head.trim()
}

function readSteps(lines: readonly string[]): DeckApexStep[] {
  const start = lines.findIndex(l => /^##\s+progress\b/i.test(l))
  if (start < 0) return []
  const steps: DeckApexStep[] = []
  for (const line of lines.slice(start + 1)) {
    if (/^##\s/.test(line)) break
    if (!line.trim().startsWith('|')) continue
    if (/^[\s|:-]+$/.test(line)) continue
    const cells = line.split('|').slice(1, -1).map(clean)
    const step = cells[0] ?? ''
    const status = cells[1] ?? ''
    if (step === '' || /^step$/i.test(step)) continue
    steps.push({ step, status, kind: statusKind(status) })
  }
  return steps
}

export function currentStep(steps: readonly DeckApexStep[]): string | undefined {
  return (steps.find(s => s.kind === 'running') ?? steps.find(s => s.kind === 'pending'))?.step
}

export function parseContext(text: string, dirName: string): DeckApexRun {
  const lines = text.replace(/\r\n?/g, '\n').split('\n')
  const headerEnd = lines.findIndex(l => /^##\s/.test(l))
  const header = headerEnd < 0 ? lines : lines.slice(0, headerEnd)

  const heading = header.find(l => /^#\s+\S/.test(l))
  const headingText = heading === undefined ? undefined : clean(heading.replace(/^#\s+/, ''))
  const apexTitle = headingText?.match(/^APEX\s*[:—–-]\s*(.+)$/i)?.[1]
  const title = clean(apexTitle ?? headingText ?? '') || dirName

  const fields = new Map<string, string>()
  for (const line of header) {
    const match = FIELD.exec(line)
    const key = match?.[1]?.trim().toLowerCase()
    const value = match?.[2]
    if (key === undefined || value === undefined || fields.has(key)) continue
    fields.set(key, clean(value))
  }

  const tierField = fields.get('tier')
  const modeField = fields.get('mode')
  const flags = fields.get('flags') ?? fields.get('flags résolus')
  const tier =
    tierField !== undefined && tierField !== ''
      ? headOf(tierField)
      : modeField !== undefined && modeField !== ''
        ? headOf(modeField)
        : flags?.match(/\bmode\s+([^\s,;)]+)/i)?.[1]

  const branch = (fields.get('branch') ?? fields.get('branche'))?.split(/\s+/)[0]

  const run: DeckApexRun = { title, steps: readSteps(lines) }
  if (tier !== undefined && tier !== '') run.tier = tier
  if (branch !== undefined && branch !== '') run.branch = branch
  const current = currentStep(run.steps)
  if (current !== undefined) run.currentStep = current
  return run
}

/**
 * Live: modified in the last `staleMs` (STALE_MS by default), its 09-finish row neither done nor
 * skipped, and, when it has a Progress table, a pending or running row left.
 */
export function isLive(run: DeckApexRun, mtimeMs: number, now: number, staleMs: number = STALE_MS): boolean {
  if (now - mtimeMs >= staleMs) return false
  const finish = run.steps.find(s => /finish/i.test(s.step))
  if (finish !== undefined && (finish.kind === 'done' || finish.kind === 'skipped')) return false
  if (run.steps.length === 0) return true
  return run.steps.some(s => s.kind === 'pending' || s.kind === 'running')
}

/** APEX's main steps in order: the pending dots of a run read from its files. */
export const KNOWN_STEPS: readonly string[] = [
  '00-init',
  '01-analyze',
  '02-plan',
  '03-execute',
  '04-validate',
  '05-examine',
  '06-resolve',
  '07-tests',
  '08-run-tests',
  '09-finish',
]

// A step file: `NN-name.md` or `NNx-name.md`; 00-context.md is the run's header, not a step.
const STEP_FILE = /^(?!00-context\.md$)(\d\d[a-z]?-.+)\.md$/
const FINISH = /^\d\d[a-z]?-finish$/

/** A run folder without 00-context.md is live only while one of its step files moved in the last hour. */
export const BARE_STALE_MS = 60 * 60 * 1000

/** The newest step file's mtime among `files`, or -Infinity when none is a step file. */
export function newestStep(files: readonly { name: string; mtimeMs: number }[]): number {
  return Math.max(-Infinity, ...files.filter(f => STEP_FILE.test(f.name)).map(f => f.mtimeMs))
}

/**
 * A run folder without 00-context.md is shown only off the trunk (HEAD neither master nor main)
 * and while its newest step file is under BARE_STALE_MS old; the rest is isLive's rule.
 */
export function bareShown(run: DeckApexRun, stepMs: number, head: string | undefined, now: number): boolean {
  if (head === 'master' || head === 'main') return false
  return isLive(run, stepMs, now, BARE_STALE_MS)
}

/**
 * The run dir a poll found against the last one seen this session: new only when a previous run
 * was seen and the dir differs. `last` survives a poll with no run (a miss, an ended run), so the
 * same run coming back is not new. From a session key the poll never finds a new run: the call
 * that set it already counted (callSwitch), and the folder it then writes is that same run.
 */
export function runSwitch(last: string | null, dir: string | null): { isNew: boolean; last: string | null } {
  if (dir === null) return { isNew: false, last }
  return { isNew: last !== null && last !== dir && !isSessionDir(last), last: dir }
}

// ---------------------------------------------------------------- session run

// A session run's key, in the run dir's place: never a folder name (a folder holds no colon here).
const SESSION_PREFIX = 'session:'

/** The run key of the main-loop Skill(apex) call started at `startedAt`. */
export const sessionKey = (startedAt: number): string => `${SESSION_PREFIX}${startedAt}`

/** A run key set by a Skill(apex) call rather than by a folder under .claude/output/apex. */
export const isSessionDir = (dir: string): boolean => dir.startsWith(SESSION_PREFIX)

/** A main-loop Skill(apex) call: a new run once any run was seen this session. */
export function callSwitch(last: string | null, key: string): { isNew: boolean; last: string } {
  return { isNew: last !== null, last: key }
}

/**
 * The run a main-loop Skill(apex) call stands for while no run folder is live: shown off the
 * trunk (HEAD neither master nor main) and under BARE_STALE_MS after the last call; HEAD as
 * header, no tier, one current `apex` row.
 */
export function sessionRunOf(at: DeckApexSessionRun | null, head: string | undefined, now: number): DeckApexRun | null {
  if (at === null || head === 'master' || head === 'main' || now - at.lastAt >= BARE_STALE_MS) return null
  const run: DeckApexRun = {
    title: 'apex',
    steps: [{ step: 'apex', status: 'in progress', kind: 'running' }],
    currentStep: 'apex',
    dir: sessionKey(at.startedAt),
  }
  if (head !== undefined) run.branch = head
  return run
}

/**
 * A run folder without 00-context.md, read from its step files: title the folder, no tier, each
 * present step done, the most recently modified one current (a finish file never: the run ended),
 * the known steps after it pending.
 */
export function runFromFiles(dirName: string, files: readonly { name: string; mtimeMs: number }[]): DeckApexRun {
  const present = new Map<string, number>()
  for (const file of files) {
    const step = STEP_FILE.exec(file.name)?.[1]
    if (step !== undefined) present.set(step, Math.max(present.get(step) ?? 0, file.mtimeMs))
  }
  let current: string | undefined
  let newest = -Infinity
  for (const [step, mtimeMs] of present) {
    // A finish file ends the run: done, never current.
    if (FINISH.test(step)) continue
    if (mtimeMs > newest || (mtimeMs === newest && current !== undefined && step > current)) {
      current = step
      newest = mtimeMs
    }
  }
  const names = new Set(present.keys())
  if (current !== undefined) for (const step of KNOWN_STEPS) if (step > current) names.add(step)
  const steps: DeckApexStep[] = [...names].sort().map(step =>
    step === current
      ? { step, status: 'in progress', kind: 'running' }
      : present.has(step)
        ? { step, status: 'complete', kind: 'done' }
        : { step, status: 'pending', kind: 'pending' },
  )
  const run: DeckApexRun = { title: dirName, steps }
  if (current !== undefined) run.currentStep = current
  return run
}

/** The branch a .git/HEAD file names, or undefined (detached HEAD, anything unrecognised). */
export function headBranch(text: string): string | undefined {
  const name = /^ref:\s*refs\/heads\/(\S+)\s*$/.exec(text.trim())?.[1]
  return name === undefined || name === '' ? undefined : name
}

/** Off-branch only when both the run's branch and HEAD's are known and differ. */
export function onBranch(run: DeckApexRun, head: string | undefined): boolean {
  return run.branch === undefined || head === undefined || run.branch === head
}

// ---------------------------------------------------------------- live steps

/** The steps in the order the row shows them; edit, gate and ship always, the rest once seen. */
export const STEP_ORDER: readonly DeckApexStepName[] = ['plan', 'edit', 'implement', 'tests', 'gate', 'Codex', 'review', 'ship']
const ALWAYS: ReadonlySet<DeckApexStepName> = new Set<DeckApexStepName>(['edit', 'gate', 'ship'])

const EDITING = new Set(['Edit', 'Write', 'NotebookEdit'])
const PLAN_PATH = /(^|\/)\.claude\/output\/apex\//
const CODEX = /apex-verify-external/
const SHIP = /\bgit\s+(commit|push)\b|\bgh\s+pr\s+(create|merge)\b/
const GATE = /nix flake check|pnpm (verify|test|typecheck|lint)|claude plugin (test|validate)|\btsc\b|cargo (check|test)/

/**
 * The step a tool call stands for, or null. Edits count from every loop; Bash (gate, Codex, ship)
 * from the main loop only: a reviewer's probes are no gate.
 */
export function classifyCall(
  tool: string,
  input: { file_path?: string; notebook_path?: string; command?: string },
  inSubagent: boolean,
): DeckApexStepName | null {
  if (EDITING.has(tool)) {
    const path = input.file_path ?? input.notebook_path ?? ''
    return PLAN_PATH.test(path) ? 'plan' : 'edit'
  }
  if (tool !== 'Bash' || inSubagent) return null
  const command = input.command ?? ''
  if (CODEX.test(command)) return 'Codex'
  if (SHIP.test(command)) return 'ship'
  if (GATE.test(command)) return 'gate'
  return null
}

const IMPLEMENTERS = new Set(['frontend-expert', 'backend-expert', 'nix-expert', 'debugger', 'quick-fix'])
const REVIEWERS = new Set(['code-reviewer', 'security-auditor'])

/** The step a spawned agent stands for (its type's last `:` segment), or null. */
export function classifyAgent(subagentType: string): 'implement' | 'tests' | 'review' | null {
  const type = subagentType.split(':').pop() ?? subagentType
  if (IMPLEMENTERS.has(type)) return 'implement'
  if (type === 'test-runner') return 'tests'
  if (REVIEWERS.has(type)) return 'review'
  return null
}

/** The external verification's verdict line in a Bash output, or null. */
export function parseCodex(output: string): { verdict: string; findings: number } | null {
  const match = /EXTERNAL-VERIFY (PASS|FAIL|BLOCKED)\b(?:.*?findings=(\d+))?/.exec(output)
  const verdict = match?.[1]
  if (verdict === undefined) return null
  return { verdict, findings: Number(match?.[2] ?? 0) }
}

// A report line without its markdown: `**`, heading `#`s, list bullets' leading spaces.
const bare = (line: string): string => line.replace(/\*\*/g, '').replace(/^\s*#+\s*/, '').trim()
const LABELLED = /^\s*verdict\s*:\s*(APPROVED|NEEDS_FIXES|BLOCKED)\b/i
const LEADING = /^(APPROVED|NEEDS_FIXES|BLOCKED)\b/

const nonEmpty = (text: string): string[] => text.replace(/\r\n?/g, '\n').split('\n').filter(l => l.trim() !== '')

// The verdict and the index (among the non-empty lines) of the line that carries it.
function reviewVerdict(lines: readonly string[]): { verdict: string; at: number } | null {
  // A labelled `Verdict: X` line wins: a first line may open with the word as prose ("BLOCKED by X").
  for (const [at, line] of lines.entries()) {
    const word = LABELLED.exec(bare(line))?.[1]
    if (word !== undefined) return { verdict: word.toUpperCase(), at }
  }
  const first = lines[0]
  const word = first === undefined ? undefined : LEADING.exec(bare(first))?.[1]
  return word === undefined ? null : { verdict: word, at: 0 }
}

/**
 * A reviewer's verdict, anchored: a `Verdict: X` line, else a first non-empty line that is (or
 * starts with) APPROVED, NEEDS_FIXES or BLOCKED; else null. The word in later prose is ignored.
 */
export function parseReview(answer: string): string | null {
  return reviewVerdict(nonEmpty(answer))?.verdict ?? null
}

/** The first 3 non-empty lines of a review after its verdict line (from the top without one), shortened. */
export function reviewLines(answer: string): string[] {
  const lines = nonEmpty(answer)
  const v = reviewVerdict(lines)
  return lines.slice(v === null ? 0 : v.at + 1, (v === null ? 0 : v.at + 1) + 3).map(l => shorten(l, 100))
}

/** The first 2 non-empty lines of an agent's final answer, shortened. */
export function answerLines(answer: string): string[] {
  return nonEmpty(answer)
    .slice(0, 2)
    .map(l => shorten(l, 100))
}

/** A path's last two segments: `hooks/apex.ts`. */
export function pathTail(path: string): string {
  return path.split('/').filter(p => p !== '').slice(-2).join('/')
}

type BashOutput = { stdout?: string; stderr?: string; returnCodeInterpretation?: string }

const lastLineOf = (text: string): string | undefined => {
  const last = nonEmpty(text).pop()
  return last === undefined ? undefined : shorten(last, 100)
}

/** A gate call's evidence: its command, the exit code its output names, its error flag, its last output line. */
export function gateEvidence(
  command: string,
  out: BashOutput,
  isError: boolean,
): Pick<DeckApexLiveStep, 'command' | 'exitCode' | 'isError' | 'lastLine'> {
  const all = [out.stdout ?? '', out.stderr ?? '', out.returnCodeInterpretation ?? ''].join('\n')
  const code = /\bexit(?:ed with)?(?: code| status)?[\s:]+(\d+)\b/i.exec(all)?.[1]
  const last = lastLineOf(`${out.stdout ?? ''}\n${out.stderr ?? ''}`)
  return {
    command: shorten(command, 80),
    ...(code === undefined ? {} : { exitCode: Number(code) }),
    isError,
    ...(last === undefined ? {} : { lastLine: last }),
  }
}

/** A ship call's evidence: its command, the commit subject `-m` gives (a heredoc's first line too), a PR URL. */
export function shipEvidence(command: string, stdout: string): Pick<DeckApexLiveStep, 'command' | 'subject' | 'url'> {
  const heredoc = /\bgit\s+commit\b[\s\S]*?-m\s+["']?\$\(cat\s+<<-?\s*['"]?\w+['"]?\s*\n\s*([^\n]+)/.exec(command)?.[1]
  const quoted = /\bgit\s+commit\b[^\n]*?\s-m\s*(?:"([^"\n]*)"|'([^'\n]*)'|([^\s"'$][^\s]*))/.exec(command)
  const subject = heredoc ?? quoted?.[1] ?? quoted?.[2] ?? quoted?.[3]
  const url = /https:\/\/github\.com\/[^\s/]+\/[^\s/]+\/pull\/\d+/.exec(stdout)?.[0]
  return {
    command: shorten(command.split('\n')[0] ?? command, 80),
    ...(subject === undefined || subject.trim() === '' ? {} : { subject: shorten(subject, 80) }),
    ...(url === undefined ? {} : { url }),
  }
}

/** A `gh pr merge` call: the run is at rest once its turn completes. */
export const isMergeCall = (command: string): boolean => /\bgh\s+pr\s+merge\b/.test(command)

/**
 * When the run came to rest, or null while it is busy: the main turn completed (`turnEndAt`) and
 * no agent card or shell of the run (started since `startedAt`) still runs, or a merge was seen.
 * The rest time is the latest of the turn end, an agent end, a shell end.
 */
export function runEndedAt(
  run: { startedAt: number; turnEndAt?: number | null; merged?: boolean },
  cards: readonly { spawnedAt: number; endedAt: number | null; status: string }[],
  shells: readonly { startedAt: number; endedAt?: number; status: string }[],
): number | null {
  const turnEnd = run.turnEndAt
  if (turnEnd === undefined || turnEnd === null) return null
  const ownCards = cards.filter(c => c.spawnedAt >= run.startedAt)
  const ownShells = shells.filter(x => x.startedAt >= run.startedAt)
  const isBusy = ownCards.some(c => c.status === 'running') || ownShells.some(x => x.status === 'running')
  if (isBusy && run.merged !== true) return null
  const ends = [...ownCards.map(c => c.endedAt), ...ownShells.map(x => x.endedAt)].filter((t): t is number => typeof t === 'number')
  return Math.max(turnEnd, ...ends)
}

/** A model id's family (`Opus`), else the id itself. */
export function modelFamily(id: string): string {
  const family = /(opus|sonnet|haiku|fable)/i.exec(id)?.[1]
  return family === undefined ? id : family.charAt(0).toUpperCase() + family.slice(1).toLowerCase()
}

export const NO_STEPS: DeckApexSteps = { runKey: null, steps: [], current: null }

/** A run's steps, none seen yet. */
export const startSteps = (runKey: string): DeckApexSteps => ({ runKey, steps: [], current: null })

/** Step `name` seen at `at` in run `runKey` (another run's steps start over); it becomes current. */
export function seeStep(
  s: DeckApexSteps,
  runKey: string,
  name: DeckApexStepName,
  at: number,
  extra: Omit<DeckApexLiveStep, 'name' | 'status' | 'at'> = {},
): DeckApexSteps {
  const base = s.runKey === runKey ? s : startSteps(runKey)
  const prev = base.steps.find(x => x.name === name)
  // Files add up (distinct, bounded); a ship's subject and PR URL survive its later calls.
  const files = [...new Set([...(prev?.files ?? []), ...(extra.files ?? [])])].slice(0, MAX_FILES)
  const subject = extra.subject ?? prev?.subject
  const url = extra.url ?? prev?.url
  const step: DeckApexLiveStep = {
    name,
    status: 'seen',
    at,
    ...extra,
    ...(files.length === 0 ? {} : { files }),
    ...(subject === undefined ? {} : { subject }),
    ...(url === undefined ? {} : { url }),
  }
  return { runKey, steps: [...base.steps.filter(x => x.name !== name), step], current: name }
}

// Distinct files a step keeps: enough to count « +N more » past the 6 shown.
const MAX_FILES = 40
const SHOWN_FILES = 6

/**
 * Agent `agentId`'s step ended at `at`, with its verdict if any and what its answer said; the same
 * reference when no step is its.
 */
export function endAgent(
  s: DeckApexSteps,
  agentId: string,
  at: number,
  verdict: string | null,
  end: Pick<DeckApexLiveStep, 'lines' | 'isFailed'> = {},
): DeckApexSteps {
  if (!s.steps.some(x => x.agentId === agentId && x.endedAt === undefined)) return s
  return {
    ...s,
    steps: s.steps.map(x =>
      x.agentId === agentId && x.endedAt === undefined ? { ...x, endedAt: at, ...(verdict === null ? {} : { verdict }), ...end } : x,
    ),
  }
}

const WARN_VERDICTS = new Set(['FAIL', 'BLOCKED', 'ERROR', 'NEEDS_FIXES'])

export type StepMark = 'done' | 'current' | 'pending'

export type StepCell = { name: DeckApexStepName; label: string; mark: StepMark; isWarn: boolean }

const isRunning = (x: DeckApexLiveStep): boolean => x.agentId !== undefined && x.endedAt === undefined

// A step with a verdict is done; the current one, or one whose agent still runs, is ◐.
const markOf = (s: DeckApexSteps, x: DeckApexLiveStep): StepMark =>
  x.verdict !== undefined ? 'done' : x.name === s.current || isRunning(x) ? 'current' : 'done'

/** The step row: label (with its verdict and findings), mark, warn colour. */
export function stepCells(s: DeckApexSteps): StepCell[] {
  const cells: StepCell[] = []
  for (const name of STEP_ORDER) {
    const x = s.steps.find(y => y.name === name)
    if (x === undefined) {
      if (ALWAYS.has(name)) cells.push({ name, label: name, mark: 'pending', isWarn: false })
      continue
    }
    const findings = x.findings !== undefined && x.findings > 0 ? ` ${x.findings}` : ''
    const label = x.verdict === undefined ? name : `${name} ${x.verdict}${findings}`
    cells.push({ name, label, mark: markOf(s, x), isWarn: x.verdict !== undefined && WARN_VERDICTS.has(x.verdict) })
  }
  return cells
}

export type StepDetail = { name: DeckApexStepName; mark: StepMark; text: string; since?: number }

const detailOf = (s: DeckApexSteps, x: DeckApexLiveStep): StepDetail | null => {
  if (isRunning(x) && x.detail !== undefined) return { name: x.name, mark: markOf(s, x), text: `${x.name} : ${x.detail}`, since: x.at }
  if (x.verdict === undefined) return null
  const findings = x.findings !== undefined && x.findings > 0 ? ` · ${x.findings} findings` : ''
  return { name: x.name, mark: markOf(s, x), text: `${x.name} : ${x.verdict}${findings}` }
}

/** The line under the row: the current step's agent (running) or verdict, else a still running agent's. */
export function stepDetail(s: DeckApexSteps): StepDetail | null {
  const current = s.steps.find(x => x.name === s.current)
  const own = current === undefined ? null : detailOf(s, current)
  if (own !== null) return own
  const running = [...s.steps].reverse().find(x => isRunning(x) && x.detail !== undefined)
  return running === undefined ? null : detailOf(s, running)
}

/** A step's explanation box: its lines, and when a still running agent started (its live clock). */
export type StepExplain = { lines: string[]; since?: number }

// An agent step's head line: description (model), status, duration once ended.
const agentLine = (x: DeckApexLiveStep): string => {
  const what = x.detail ?? x.name
  if (x.endedAt === undefined) return `${what} · running`
  return `${what} · ${x.isFailed === true ? 'failed' : 'done'} · ${fmtTimer(x.endedAt - x.at)}`
}

/** What a step did, as its explanation box shows it; a step never seen is not reached yet. */
export function explainStep(s: DeckApexSteps, name: DeckApexStepName): StepExplain {
  const x = s.steps.find(y => y.name === name)
  if (x === undefined) return { lines: ['not reached yet'] }
  const running = x.agentId !== undefined && x.endedAt === undefined ? { since: x.at } : {}
  switch (name) {
    case 'plan':
    case 'edit': {
      const files = x.files ?? []
      if (files.length === 0) return { lines: [name === 'plan' ? 'run files written' : 'files edited'] }
      const more = files.length > SHOWN_FILES ? ` +${files.length - SHOWN_FILES} more` : ''
      return { lines: [`${files.slice(0, SHOWN_FILES).join(', ')}${more}`] }
    }
    case 'implement':
    case 'tests':
      return { lines: [agentLine(x), ...(x.lines ?? []).slice(0, 2)], ...running }
    case 'review': {
      const head = x.endedAt === undefined ? agentLine(x) : `${x.verdict ?? 'no verdict'} · ${agentLine(x)}`
      return { lines: [head, ...(x.lines ?? []).slice(0, 3)], ...running }
    }
    case 'gate': {
      const status = x.exitCode !== undefined ? `exit ${x.exitCode}` : x.isError === true ? 'failed' : 'ok'
      const tail = x.lastLine === undefined ? '' : ` · ${x.lastLine}`
      return { lines: [`$ ${x.command ?? 'gate'}`, `${status}${tail}`] }
    }
    case 'Codex': {
      if (x.verdict === undefined) return { lines: ['no verdict (ran in background)'] }
      return { lines: [`${x.verdict} · ${x.findings ?? 0} findings`] }
    }
    case 'ship': {
      const head = x.subject !== undefined ? `commit: ${x.subject}` : `$ ${x.command ?? 'ship'}`
      return { lines: [head, ...(x.url === undefined ? [] : [`PR: ${x.url}`])] }
    }
  }
}

// ---------------------------------------------------------------- verdict

const VERDICTS = new Set(['PASS', 'FAIL', 'BLOCKED', 'ERROR'])

/** The verdict word and findings count of an external-verify.json text, or null when it is not one. */
export function parseVerdict(text: string): { verdict: string; findings: number } | null {
  let data: unknown
  try {
    data = JSON.parse(text)
  } catch {
    // Not JSON (half-written, or another file): no verdict to show.
    return null
  }
  if (typeof data !== 'object' || data === null) return null
  const word: unknown = Reflect.get(data, 'verdict')
  const findings: unknown = Reflect.get(data, 'findings')
  if (typeof word !== 'string' || !VERDICTS.has(word)) return null
  return { verdict: word, findings: Array.isArray(findings) ? findings.length : 0 }
}

// ---------------------------------------------------------------- what the block and the log show

export type PhaseMark = 'done' | 'current' | 'pending' | 'failed' | 'skipped'

/** A step's dot: ● done, ◐ current, ○ pending; a failed step ✗, a skipped one ·. */
export function phaseMark(step: DeckApexStep, current: string | undefined): PhaseMark {
  if (step.kind === 'failed') return 'failed'
  if (step.step === current || step.kind === 'running') return 'current'
  if (step.kind === 'done') return 'done'
  if (step.kind === 'skipped') return 'skipped'
  return 'pending'
}

export const PHASE_GLYPH: Record<PhaseMark, string> = { done: '●', current: '◐', pending: '○', failed: '✗', skipped: '·' }

/** The block's header: `APEX · <branch, else title> · <tier>`. */
export function apexHeader(run: DeckApexRun): string {
  return ['APEX', run.branch ?? run.title, run.tier].filter((p): p is string => p !== undefined && p !== '').join(' · ')
}

/**
 * The log line a poll owes: a run found (its current step), a step that moved, a run gone; null
 * when nothing moved. Only the current step and the run's directory count.
 */
export function phaseNote(prev: DeckApexRun | null, next: DeckApexRun | null): string | null {
  if (next === null) return prev === null ? null : 'run ended'
  if (prev === null || prev.dir !== next.dir) return `${next.branch ?? next.title} · ${next.currentStep ?? 'started'}`
  if (prev.currentStep === next.currentStep) return null
  return `${prev.currentStep ?? '—'} → ${next.currentStep ?? 'done'}`
}

/** Polls in a row that must miss a live run before it counts as ended: one failed read is not an end. */
export const END_MISSES = 2

/**
 * The run a poll keeps: what it found, or, while a run shown before is missed fewer than
 * END_MISSES times in a row, that run still; `misses` is the count carried to the next poll.
 */
export function settleRun(prev: DeckApexRun | null, found: DeckApexRun | null, misses: number): { run: DeckApexRun | null; misses: number } {
  if (found !== null || prev === null) return { run: found, misses: 0 }
  const missed = misses + 1
  return missed >= END_MISSES ? { run: null, misses: 0 } : { run: prev, misses: missed }
}

